def _strategy_head(strategy_id: Any) -> str:
    raw = str(strategy_id)
    for alias, head in HEAD_ALIASES.items():
        if raw == alias or raw.startswith(f"{alias}_"):
            return head
    for prefix in HEAD_PREFIXES:
        if raw == prefix or raw.startswith(f"{prefix}_"):
            return prefix
    return "unknown"
