def _lgbm_deterministic_kwargs(seed: int) -> dict[str, Any]:
    """LightGBM settings that make sparse policy comparisons reproducible.

    These models are used to compare small numbers of interventions. A single
    false selected action can flip a run, so multi-thread histogram variation is
    too noisy for this script's promotion gates.
    """

    seed_i = int(seed)
    return {
        "random_state": seed_i,
        "bagging_seed": seed_i,
        "feature_fraction_seed": seed_i,
        "data_random_seed": seed_i,
        "extra_seed": seed_i,
        "deterministic": True,
        "force_col_wise": True,
        "n_jobs": 1,
    }


def _parse_selected_arms(value: str | None) -> set[str]:
    if value is None or not str(value).strip() or str(value).strip().lower() == "all":
        return set(DEFAULT_ARMS)
    selected: set[str] = set()
    aliases = {arm.split("_", 1)[0].lower(): arm for arm in DEFAULT_ARMS}
    aliases.update({arm.lower(): arm for arm in DEFAULT_ARMS})
    for raw in str(value).split(","):
        token = raw.strip()
        if not token:
            continue
        if token.lower() == "all":
            return set(DEFAULT_ARMS)
        arm = aliases.get(token.lower())
        if arm is None:
            valid = ", ".join([arm.split("_", 1)[0] for arm in DEFAULT_ARMS])
            raise ValueError(f"Unknown arm '{token}'. Use full arm names or short codes: {valid}")
        selected.add(arm)
    if "C0_baseline" not in selected:
        selected.add("C0_baseline")
    if not selected:
        selected = set(DEFAULT_ARMS)
    return selected


def _numeric_cols(frame: pd.DataFrame, exclude: set[str]) -> list[str]:
    return [c for c in frame.columns if c not in exclude and pd.api.types.is_numeric_dtype(frame[c])]


