def _add_opportunity_recall_score(frame: pd.DataFrame) -> pd.DataFrame:
    out = frame.copy()
    score = pd.Series(0.0, index=out.index, dtype=float)
    used = 0
    for col in _OPPORTUNITY_RECALL_SCORE_FEATURES:
        if col not in out.columns:
            continue
        vals = pd.to_numeric(out[col], errors="coerce").replace([np.inf, -np.inf], np.nan)
        if vals.notna().sum() <= 0:
            continue
        lo = float(vals.quantile(0.05))
        hi = float(vals.quantile(0.95))
        if not np.isfinite(lo) or not np.isfinite(hi) or hi <= lo:
            scaled = vals.fillna(vals.median()).fillna(0.0)
            if scaled.abs().max() > 1.0:
                scaled = np.log1p(scaled.clip(lower=0.0))
                denom = float(scaled.max())
                scaled = scaled / denom if denom > 0.0 else scaled * 0.0
        else:
            scaled = ((vals - lo) / (hi - lo)).clip(lower=0.0, upper=1.0).fillna(0.0)
        score = score + scaled.astype(float)
        used += 1
    out["opportunity_recall_score"] = score / max(used, 1)
    return out


def _choose_strategy_opportunity_fixed_gates(
    scored_groups: pd.DataFrame,
    panel: pd.DataFrame,
    *,
    multiplier: float = 0.0,
    threshold_holdout_frac: float = 0.0,
    min_precision: float = 1.0,
    max_intervention_rate: float = 0.15,
    require_no_harm: bool = True,
    top_fractions: tuple[float, ...] = (0.005, 0.01, 0.025, 0.05, 0.075, 0.10, 0.15),
) -> tuple[pd.DataFrame, dict[str, Any]]:
    base_cols = [
        "strategy_id",
        "rule_kind",
        "feature_a",
        "threshold_a",
        "feature_b",
        "threshold_b",
        "top_fraction",
        "multiplier",
        "objective",
        "train_interventions",
        "train_precision",
        "train_delta_full_J_sum",
        "train_positive_actions",
        "train_groups",
        "threshold_source",
        "threshold_holdout_frac",
    ]
    empty_diag = {
        "objective": 0.0,
        "train_interventions": 0,
        "train_intervention_rate": 0.0,
        "train_precision": 0.0,
        "train_delta_full_J_sum": 0.0,
        "train_positive_actions": 0,
        "train_groups": 0,
        "threshold_source": "no_op_no_strategy_opportunity_edge",
        "threshold_holdout_frac": float(threshold_holdout_frac),
        "strategy_rule_count": 0,
        "require_no_harm": bool(require_no_harm),
    }
    if scored_groups.empty or panel.empty:
        return pd.DataFrame(columns=base_cols), empty_diag
    groups = _add_opportunity_recall_score(scored_groups)
    groups["timestamp"] = pd.to_datetime(groups["timestamp"], utc=True, errors="coerce")
    groups["strategy_id"] = groups["strategy_id"].astype(str)
    groups = _chronological_threshold_holdout(groups, holdout_frac=float(threshold_holdout_frac))
    pnl = panel.copy()
    pnl["timestamp"] = pd.to_datetime(pnl["timestamp"], utc=True, errors="coerce")
    pnl["strategy_id"] = pnl["strategy_id"].astype(str)
    pnl["multiplier"] = pd.to_numeric(pnl.get("multiplier"), errors="coerce").fillna(1.0)
    labels = pnl.loc[np.isclose(pnl["multiplier"].to_numpy(dtype=float), float(multiplier))].copy()
    if groups.empty or labels.empty:
        return pd.DataFrame(columns=base_cols), empty_diag
    label_cols = ["timestamp", "strategy_id", "delta_full_J", "action_binds"]
    work = groups.merge(labels[label_cols].drop_duplicates(["timestamp", "strategy_id"]), on=["timestamp", "strategy_id"], how="left")
    for col in set(_OPPORTUNITY_RECALL_MIN_FEATURES + _OPPORTUNITY_RECALL_MAX_FEATURES + ["group_can_bind", "delta_full_J", "action_binds", "opportunity_recall_score"]):
        raw = work[col] if col in work.columns else pd.Series(np.nan, index=work.index)
        work[col] = pd.to_numeric(raw, errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
    work = work.loc[(work["group_can_bind"] > 0.0) & (work["action_binds"] > 0.0)].copy()
    if work.empty:
        return pd.DataFrame(columns=base_cols), empty_diag

    def _feature_thresholds(part: pd.DataFrame, col: str, qs: tuple[float, ...]) -> list[float]:
        vals = pd.to_numeric(part.get(col), errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
        if vals.empty or vals.nunique() <= 1:
            return []
        return sorted(set(float(vals.quantile(q)) for q in qs))

    rows: list[dict[str, Any]] = []
    total_groups = 0
    total_interventions = 0
    total_positives = 0
    total_delta = 0.0
    total_objective = 0.0
    for strategy_id, part in work.groupby("strategy_id", sort=False):
        part = part.copy()
        group_count = int(part[["timestamp", "strategy_id"]].drop_duplicates().shape[0])
        total_groups += group_count
        if group_count <= 0:
            continue
        candidate_rules: list[dict[str, Any]] = [{"rule_kind": "top_score", "feature_a": "", "threshold_a": np.nan, "feature_b": "", "threshold_b": np.nan}]
        min_cols = [c for c in _OPPORTUNITY_RECALL_MIN_FEATURES if c in part.columns and pd.to_numeric(part[c], errors="coerce").nunique(dropna=True) > 1]
        max_cols = [c for c in _OPPORTUNITY_RECALL_MAX_FEATURES if c in part.columns and pd.to_numeric(part[c], errors="coerce").nunique(dropna=True) > 1]
        for col in min_cols:
            for threshold in _feature_thresholds(part, col, (0.50, 0.65, 0.75, 0.85)):
                candidate_rules.append({"rule_kind": "min", "feature_a": col, "threshold_a": threshold, "feature_b": "", "threshold_b": np.nan})
        for col in max_cols:
            for threshold in _feature_thresholds(part, col, (0.15, 0.25, 0.35, 0.50)):
                candidate_rules.append({"rule_kind": "max", "feature_a": col, "threshold_a": threshold, "feature_b": "", "threshold_b": np.nan})
        pair_min_cols = [
            c
            for c in min_cols
            if c
            in {
                "strategy_candidate_count",
                "strategy_above_threshold_count",
                "strategy_rank_q90",
                "timestamp_rank_q90",
                "strategy_candidate_occupied_symbol_share",
                "positions_exiting_1h",
                "notional_exiting_1h_share",
                "side_open_hhi",
                "side_notional_hhi",
                "cooldown_count",
                "strategy_expected_cost_mean",
                "strategy_expected_cost_q75",
                "group_affected_notional",
            }
        ]
        pair_max_cols = [c for c in max_cols if c in {"strategy_open_count", "side_open_hhi", "side_notional_hhi", "remaining_slots"}]
        for min_col in pair_min_cols:
            for max_col in pair_max_cols:
                min_thresholds = _feature_thresholds(part, min_col, (0.50, 0.75))
                max_thresholds = _feature_thresholds(part, max_col, (0.25, 0.50))
                for min_threshold in min_thresholds:
                    for max_threshold in max_thresholds:
                        candidate_rules.append({
                            "rule_kind": "min_max",
                            "feature_a": min_col,
                            "threshold_a": min_threshold,
                            "feature_b": max_col,
                            "threshold_b": max_threshold,
                        })

        best: dict[str, Any] | None = None
        best_objective = 0.0
        for rule in candidate_rules:
            eligible = pd.Series(True, index=part.index, dtype=bool)
            kind = str(rule.get("rule_kind", "top_score"))
            feature_a = str(rule.get("feature_a", ""))
            feature_b = str(rule.get("feature_b", ""))
            if kind in {"min", "min_max"} and feature_a:
                eligible &= pd.to_numeric(part[feature_a], errors="coerce").fillna(-np.inf) >= float(rule["threshold_a"])
            if kind == "max" and feature_a:
                eligible &= pd.to_numeric(part[feature_a], errors="coerce").fillna(np.inf) <= float(rule["threshold_a"])
            if kind == "min_max" and feature_b:
                eligible &= pd.to_numeric(part[feature_b], errors="coerce").fillna(np.inf) <= float(rule["threshold_b"])
            base = part.loc[eligible].copy()
            if base.empty:
                continue
            for top_fraction in top_fractions:
                n_top = max(1, int(np.ceil(group_count * float(top_fraction))))
                chosen = base.nlargest(min(n_top, len(base)), "opportunity_recall_score").copy()
                interventions = int(len(chosen))
                if interventions <= 0:
                    continue
                rate = float(interventions / max(group_count, 1))
                if rate > float(max_intervention_rate):
                    continue
                realized = pd.to_numeric(chosen["delta_full_J"], errors="coerce").fillna(0.0)
                total = float(realized.sum())
                positives = int((realized > MATERIAL_DELTA_EPS).sum())
                precision = float(positives / max(interventions, 1))
                harmful = float(realized.clip(upper=0.0).abs().sum())
                if positives <= 0 or total <= 0.0 or precision < float(min_precision):
                    continue
                if bool(require_no_harm) and harmful > 1e-9:
                    continue
                objective = total * precision / np.sqrt(max(interventions, 1))
                if objective > best_objective:
                    best_objective = float(objective)
                    best = {
                        **rule,
                        "strategy_id": str(strategy_id),
                        "top_fraction": float(top_fraction),
                        "multiplier": float(multiplier),
                        "objective": float(objective),
                        "train_interventions": interventions,
                        "train_intervention_rate": rate,
                        "train_precision": precision,
                        "train_delta_full_J_sum": total,
                        "train_positive_actions": positives,
                        "train_groups": group_count,
                        "threshold_source": "holdout_strategy_opportunity_grid" if float(threshold_holdout_frac) > 0.0 else "training_strategy_opportunity_grid",
                        "threshold_holdout_frac": float(threshold_holdout_frac),
                    }
        if best is None:
            continue
        rows.append(best)
        total_interventions += int(best.get("train_interventions", 0))
        total_positives += int(best.get("train_positive_actions", 0))
        total_delta += float(best.get("train_delta_full_J_sum", 0.0))
        total_objective += float(best.get("objective", 0.0))

    if total_interventions <= 0:
        return pd.DataFrame(rows, columns=base_cols), empty_diag | {"train_groups": int(total_groups)}
    diag = {
        "objective": float(total_objective),
        "train_interventions": int(total_interventions),
        "train_intervention_rate": float(total_interventions / max(total_groups, 1)),
        "train_precision": float(total_positives / max(total_interventions, 1)),
        "train_delta_full_J_sum": float(total_delta),
        "train_positive_actions": int(total_positives),
        "train_groups": int(total_groups),
        "threshold_source": "holdout_strategy_opportunity_grid" if float(threshold_holdout_frac) > 0.0 else "training_strategy_opportunity_grid",
        "threshold_holdout_frac": float(threshold_holdout_frac),
        "strategy_rule_count": int(len(rows)),
        "require_no_harm": bool(require_no_harm),
    }
    return pd.DataFrame(rows, columns=base_cols + ["train_intervention_rate"]), diag


def _strategy_opportunity_fixed_schedule(scored_groups: pd.DataFrame, strategy_thresholds: pd.DataFrame) -> pd.DataFrame:
    if scored_groups.empty:
        return pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier"])
    work = _add_opportunity_recall_score(scored_groups)
    work["timestamp"] = pd.to_datetime(work["timestamp"], utc=True, errors="coerce")
    work["strategy_id"] = work["strategy_id"].astype(str)
    work["group_can_bind"] = pd.to_numeric(work.get("group_can_bind"), errors="coerce").fillna(0.0)
    for col in set(_OPPORTUNITY_RECALL_MIN_FEATURES + _OPPORTUNITY_RECALL_MAX_FEATURES):
        raw = work[col] if col in work.columns else pd.Series(np.nan, index=work.index)
        work[col] = pd.to_numeric(raw, errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
    work["stage1_group_pass"] = False
    work["multiplier"] = 1.0
    work["selection_score"] = 0.0
    if strategy_thresholds.empty:
        return work[["timestamp", "strategy_id", "multiplier", "selection_score", "opportunity_recall_score", "stage1_group_pass"]].sort_values(["timestamp", "strategy_id"])
    thresholds = strategy_thresholds.copy()
    thresholds["strategy_id"] = thresholds["strategy_id"].astype(str)
    for row in thresholds.itertuples(index=False):
        strategy_id = str(row.strategy_id)
        idx = work.index[work["strategy_id"].eq(strategy_id) & (work["group_can_bind"] > 0.0)]
        if len(idx) <= 0:
            continue
        kind = str(getattr(row, "rule_kind", "top_score"))
        feature_a = str(getattr(row, "feature_a", ""))
        feature_b = str(getattr(row, "feature_b", ""))
        eligible = pd.Series(True, index=idx, dtype=bool)
        if kind in {"min", "min_max"} and feature_a and feature_a in work.columns:
            eligible &= pd.to_numeric(work.loc[idx, feature_a], errors="coerce").fillna(-np.inf) >= float(getattr(row, "threshold_a", np.nan))
        if kind == "max" and feature_a and feature_a in work.columns:
            eligible &= pd.to_numeric(work.loc[idx, feature_a], errors="coerce").fillna(np.inf) <= float(getattr(row, "threshold_a", np.nan))
        if kind == "min_max" and feature_b and feature_b in work.columns:
            eligible &= pd.to_numeric(work.loc[idx, feature_b], errors="coerce").fillna(np.inf) <= float(getattr(row, "threshold_b", np.nan))
        idx = eligible[eligible].index
        if len(idx) <= 0:
            continue
        top_fraction = float(getattr(row, "top_fraction", 0.0))
        if top_fraction > 0.0:
            n_top = max(1, int(np.ceil(len(idx) * min(max(top_fraction, 0.0), 1.0))))
            idx = work.loc[idx].nlargest(min(n_top, len(idx)), "opportunity_recall_score").index
        fixed_multiplier = float(np.clip(float(getattr(row, "multiplier", 0.0)), 0.0, 1.0))
        work.loc[idx, "stage1_group_pass"] = True
        work.loc[idx, "multiplier"] = fixed_multiplier
        work.loc[idx, "selection_score"] = work.loc[idx, "opportunity_recall_score"].to_numpy(dtype=float)
    keep = ["timestamp", "strategy_id", "multiplier", "selection_score", "opportunity_recall_score", "stage1_group_pass"]
    return work[[c for c in keep if c in work.columns]].sort_values(["timestamp", "strategy_id"])


def _secondary_acceptance_feature_rows(schedule: pd.DataFrame, panel: pd.DataFrame, *, include_labels: bool) -> pd.DataFrame:
    if schedule.empty:
        return pd.DataFrame()
    sched = schedule.copy()
    sched["timestamp"] = pd.to_datetime(sched["timestamp"], utc=True, errors="coerce")
    sched["strategy_id"] = sched["strategy_id"].astype(str)
    sched["multiplier"] = pd.to_numeric(sched.get("multiplier"), errors="coerce").fillna(1.0)
    sched = sched.loc[(sched["multiplier"] < 1.0) & sched["timestamp"].notna()].copy()
    if sched.empty:
        return pd.DataFrame()
    for col in ["selection_score", "p_intervene", "stage1_cal_positive_rate", "stage1_cal_mean_gain", "stage1_cal_lcb_mean_gain"]:
        raw = sched[col] if col in sched.columns else pd.Series(np.nan, index=sched.index)
        sched[col] = pd.to_numeric(raw, errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)

    features = panel.copy()
    features["timestamp"] = pd.to_datetime(features["timestamp"], utc=True, errors="coerce")
    features["strategy_id"] = features["strategy_id"].astype(str)
    features["multiplier"] = pd.to_numeric(features.get("multiplier"), errors="coerce").fillna(1.0)
    group_feature_cols = [c for c in _SECONDARY_GROUP_ACCEPTANCE_FEATURES if c in features.columns]
    group_features = features[["timestamp", "strategy_id"] + group_feature_cols].drop_duplicates(["timestamp", "strategy_id"])
    out = sched.merge(group_features, on=["timestamp", "strategy_id"], how="left", suffixes=("", "_panel"))

    action_feature_cols = [c for c in _SECONDARY_ACTION_ACCEPTANCE_FEATURES if c in features.columns]
    if action_feature_cols:
        action_features = features[["timestamp", "strategy_id", "multiplier"] + action_feature_cols].drop_duplicates(
            ["timestamp", "strategy_id", "multiplier"]
        )
        out = out.merge(action_features, on=["timestamp", "strategy_id", "multiplier"], how="left", suffixes=("", "_action"))

    for col in _SECONDARY_ACCEPTANCE_FEATURES:
        panel_col = f"{col}_panel"
        if panel_col in out.columns:
            base = pd.to_numeric(out.get(col), errors="coerce") if col in out.columns else pd.Series(np.nan, index=out.index)
            out[col] = base.fillna(pd.to_numeric(out[panel_col], errors="coerce"))
            out = out.drop(columns=[panel_col])
        action_col = f"{col}_action"
        if action_col in out.columns:
            base = pd.to_numeric(out.get(col), errors="coerce") if col in out.columns else pd.Series(np.nan, index=out.index)
            out[col] = base.fillna(pd.to_numeric(out[action_col], errors="coerce"))
            out = out.drop(columns=[action_col])
        raw = out[col] if col in out.columns else pd.Series(np.nan, index=out.index)
        out[col] = pd.to_numeric(raw, errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
    if include_labels:
        labels = features[
            [
                "timestamp",
                "strategy_id",
                "multiplier",
                "delta_full_J",
                "delta_immediate_J",
                "action_binds",
                "best_gain",
                "best_margin",
                "y_intervene",
            ]
        ].drop_duplicates(["timestamp", "strategy_id", "multiplier"])
        out = out.merge(labels, on=["timestamp", "strategy_id", "multiplier"], how="left")
        for col in ["delta_full_J", "delta_immediate_J", "action_binds", "best_gain", "best_margin", "y_intervene"]:
            out[col] = pd.to_numeric(out.get(col), errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
    return out


def _secondary_acceptance_mask(frame: pd.DataFrame, rule: dict[str, Any]) -> pd.Series:
    if frame.empty:
        return pd.Series(False, index=frame.index, dtype=bool)
    if not bool(rule.get("enabled", False)):
        return pd.Series(True, index=frame.index, dtype=bool)
    keep = pd.Series(True, index=frame.index, dtype=bool)
    for col, threshold in dict(rule.get("min_thresholds", {})).items():
        keep &= pd.to_numeric(frame.get(col), errors="coerce").fillna(-np.inf) >= float(threshold)
    for col, threshold in dict(rule.get("max_thresholds", {})).items():
        keep &= pd.to_numeric(frame.get(col), errors="coerce").fillna(np.inf) <= float(threshold)
    return keep


def _choose_secondary_schedule_acceptance(
    schedule: pd.DataFrame,
    panel: pd.DataFrame,
    *,
    threshold_holdout_frac: float = 0.0,
    min_precision: float = 0.80,
    require_no_harm: bool = False,
) -> tuple[dict[str, Any], dict[str, Any]]:
    rule: dict[str, Any] = {"enabled": False, "min_thresholds": {}, "max_thresholds": {}}
    diag: dict[str, Any] = {
        "objective": 0.0,
        "train_interventions": 0,
        "train_intervention_rate": 0.0,
        "train_precision": 0.0,
        "train_delta_full_J_sum": 0.0,
        "train_positive_actions": 0,
        "train_groups": 0,
        "threshold_source": "no_op_no_secondary_acceptance_edge",
        "threshold_holdout_frac": float(threshold_holdout_frac),
        "secondary_acceptance_feature_count": 0,
        "require_no_harm": bool(require_no_harm),
    }
    rows = _secondary_acceptance_feature_rows(schedule, panel, include_labels=True)
    if rows.empty:
        return rule, diag
    schedule_groups = schedule.copy()
    schedule_groups["timestamp"] = pd.to_datetime(schedule_groups["timestamp"], utc=True, errors="coerce")
    schedule_groups["strategy_id"] = schedule_groups["strategy_id"].astype(str)
    total_group_count = int(schedule_groups[["timestamp", "strategy_id"]].drop_duplicates().shape[0])
    rows = rows.loc[pd.to_numeric(rows.get("action_binds"), errors="coerce").fillna(0.0) > 0.0].copy()
    if rows.empty:
        diag["train_groups"] = total_group_count
        return rule, diag
    rows = _chronological_threshold_holdout(rows, holdout_frac=float(threshold_holdout_frac))
    group_count = max(total_group_count, int(rows[["timestamp", "strategy_id"]].drop_duplicates().shape[0]))
    diag["train_groups"] = group_count
    if group_count <= 0:
        return rule, diag

    def _thresholds(col: str) -> list[float]:
        vals = pd.to_numeric(rows.get(col), errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
        if vals.empty or vals.nunique() <= 1:
            return []
        return sorted(set(float(vals.quantile(q)) for q in (0.25, 0.50, 0.75)))

    candidate_rules: list[dict[str, dict[str, float]]] = [{"min_thresholds": {}, "max_thresholds": {}}]
    feature_cols = [c for c in _SECONDARY_ACCEPTANCE_FEATURES if c in rows.columns]
    for col in feature_cols:
        for threshold in _thresholds(col):
            candidate_rules.append({"min_thresholds": {col: threshold}, "max_thresholds": {}})
            candidate_rules.append({"min_thresholds": {}, "max_thresholds": {col: threshold}})
    compact_cols = [
        "p_intervene",
        "stage1_cal_positive_rate",
        "stage1_cal_mean_gain",
        "stage1_cal_lcb_mean_gain",
        "strategy_candidate_count",
        "strategy_open_count",
        "open_positions",
        "remaining_slots",
    ]
    compact_cols = [c for c in compact_cols if c in rows.columns]
    for i, col_a in enumerate(compact_cols):
        for col_b in compact_cols[i + 1 :]:
            for threshold_a in _thresholds(col_a):
                for threshold_b in _thresholds(col_b):
                    candidate_rules.append({"min_thresholds": {col_a: threshold_a}, "max_thresholds": {col_b: threshold_b}})
                    candidate_rules.append({"min_thresholds": {col_b: threshold_b}, "max_thresholds": {col_a: threshold_a}})

    best_objective = 0.0
    for candidate in candidate_rules:
        candidate_rule = {"enabled": True, **candidate}
        keep = _secondary_acceptance_mask(rows, candidate_rule)
        chosen = rows.loc[keep].copy()
        interventions = int(len(chosen))
        if interventions <= 0:
            continue
        rate = float(interventions / max(group_count, 1))
        if rate > 0.15:
            continue
        realized = pd.to_numeric(chosen["delta_full_J"], errors="coerce").fillna(0.0)
        total = float(realized.sum())
        positives = int((realized > MATERIAL_DELTA_EPS).sum())
        precision = float(positives / max(interventions, 1))
        harmful = float(realized.clip(upper=0.0).abs().sum())
        removed_realized = pd.to_numeric(rows.loc[~keep, "delta_full_J"], errors="coerce").fillna(0.0)
        removed_harm = float(removed_realized.clip(upper=0.0).abs().sum())
        removed_profit = float(removed_realized.clip(lower=0.0).sum())
        if positives <= 0 or total <= 0.0 or precision < float(min_precision):
            continue
        if bool(require_no_harm) and harmful > 1e-9:
            continue
        objective = (total - 4.0 * harmful + 0.75 * removed_harm - 0.75 * removed_profit) * precision / np.sqrt(max(interventions, 1))
        if objective > best_objective:
            best_objective = float(objective)
            rule = candidate_rule
            diag = {
                "objective": float(objective),
                "train_interventions": interventions,
                "train_intervention_rate": rate,
                "train_precision": precision,
                "train_delta_full_J_sum": total,
                "train_positive_actions": positives,
                "train_groups": group_count,
                "threshold_source": "holdout_secondary_acceptance_grid" if float(threshold_holdout_frac) > 0.0 else "training_secondary_acceptance_grid",
                "threshold_holdout_frac": float(threshold_holdout_frac),
                "false_selection_penalty": harmful,
                "removed_harm": removed_harm,
                "removed_profit": removed_profit,
                "secondary_acceptance_feature_count": int(len(rule.get("min_thresholds", {})) + len(rule.get("max_thresholds", {}))),
                "require_no_harm": bool(require_no_harm),
            }
    if not bool(rule.get("enabled", False)) and float(threshold_holdout_frac) > 0.0:
        fallback_rule, fallback_diag = _choose_secondary_schedule_acceptance(
            schedule,
            panel,
            threshold_holdout_frac=0.0,
            min_precision=float(min_precision),
            require_no_harm=bool(require_no_harm),
        )
        if bool(fallback_rule.get("enabled", False)):
            fallback_diag = dict(fallback_diag)
            fallback_diag["threshold_source"] = "training_secondary_acceptance_grid_fallback"
            fallback_diag["threshold_holdout_frac"] = float(threshold_holdout_frac)
            return fallback_rule, fallback_diag
    return rule, diag


def _choose_strategy_secondary_schedule_acceptance(
    schedule: pd.DataFrame,
    panel: pd.DataFrame,
    *,
    threshold_holdout_frac: float = 0.0,
    min_precision: float = 0.80,
    require_no_harm: bool = False,
) -> tuple[dict[str, dict[str, Any]], dict[str, Any]]:
    rules: dict[str, dict[str, Any]] = {}
    diag: dict[str, Any] = {
        "objective": 0.0,
        "train_interventions": 0,
        "train_intervention_rate": 0.0,
        "train_precision": 0.0,
        "train_delta_full_J_sum": 0.0,
        "train_positive_actions": 0,
        "train_groups": 0,
        "threshold_source": "no_op_no_strategy_secondary_acceptance_edge",
        "threshold_holdout_frac": float(threshold_holdout_frac),
        "strategy_rule_count": 0,
        "require_no_harm": bool(require_no_harm),
    }
    if schedule.empty or panel.empty:
        return rules, diag
    sched = schedule.copy()
    pnl = panel.copy()
    sched["timestamp"] = pd.to_datetime(sched["timestamp"], utc=True, errors="coerce")
    pnl["timestamp"] = pd.to_datetime(pnl["timestamp"], utc=True, errors="coerce")
    sched["strategy_id"] = sched["strategy_id"].astype(str)
    pnl["strategy_id"] = pnl["strategy_id"].astype(str)
    total_interventions = 0
    total_positives = 0
    total_delta = 0.0
    total_objective = 0.0
    total_groups = 0
    sources: set[str] = set()
    for strategy_id in sorted(sched["strategy_id"].dropna().astype(str).unique()):
        strat_sched = sched.loc[sched["strategy_id"].eq(strategy_id)].copy()
        strat_panel = pnl.loc[pnl["strategy_id"].eq(strategy_id)].copy()
        if strat_sched.empty or strat_panel.empty:
            continue
        rule, strat_diag = _choose_secondary_schedule_acceptance(
            strat_sched,
            strat_panel,
            threshold_holdout_frac=float(threshold_holdout_frac),
            min_precision=float(min_precision),
            require_no_harm=bool(require_no_harm),
        )
        group_count = int(strat_diag.get("train_groups", 0))
        total_groups += group_count
        if not bool(rule.get("enabled", False)):
            continue
        rule = dict(rule)
        rule["strategy_id"] = strategy_id
        rules[strategy_id] = rule
        total_interventions += int(strat_diag.get("train_interventions", 0))
        total_positives += int(strat_diag.get("train_positive_actions", 0))
        total_delta += float(strat_diag.get("train_delta_full_J_sum", 0.0))
        total_objective += float(strat_diag.get("objective", 0.0))
        sources.add(str(strat_diag.get("threshold_source", "unknown")))
    if total_interventions <= 0:
        diag["train_groups"] = int(total_groups)
        return rules, diag
    diag = {
        "objective": float(total_objective),
        "train_interventions": int(total_interventions),
        "train_intervention_rate": float(total_interventions / max(total_groups, 1)),
        "train_precision": float(total_positives / max(total_interventions, 1)),
        "train_delta_full_J_sum": float(total_delta),
        "train_positive_actions": int(total_positives),
        "train_groups": int(total_groups),
        "threshold_source": "+".join(sorted(sources)) if sources else "strategy_secondary_acceptance_grid",
        "threshold_holdout_frac": float(threshold_holdout_frac),
        "strategy_rule_count": int(len(rules)),
        "require_no_harm": bool(require_no_harm),
    }
    return rules, diag


def _apply_secondary_schedule_acceptance(
    schedule: pd.DataFrame,
    panel: pd.DataFrame,
    rule: dict[str, Any],
    *,
    default_pass: bool = True,
) -> pd.DataFrame:
    if schedule.empty:
        return schedule.copy()
    if not bool(rule.get("enabled", False)):
        out = schedule.copy()
        if not out.empty:
            out["secondary_acceptance_pass"] = bool(default_pass)
            if not bool(default_pass):
                veto = pd.to_numeric(out.get("multiplier"), errors="coerce").fillna(1.0) < 1.0
                out.loc[veto, "multiplier"] = 1.0
                out.loc[veto, "selection_score"] = 0.0
                if "eligible_action" in out.columns:
                    out.loc[veto, "eligible_action"] = False
        return out
    out = schedule.copy()
    rows = _secondary_acceptance_feature_rows(out, panel, include_labels=False)
    if rows.empty:
        out["secondary_acceptance_pass"] = bool(default_pass)
        if not bool(default_pass):
            veto = pd.to_numeric(out.get("multiplier"), errors="coerce").fillna(1.0) < 1.0
            out.loc[veto, "multiplier"] = 1.0
            out.loc[veto, "selection_score"] = 0.0
            if "eligible_action" in out.columns:
                out.loc[veto, "eligible_action"] = False
        return out
    rows["secondary_acceptance_pass"] = _secondary_acceptance_mask(rows, rule)
    keep = rows[["timestamp", "strategy_id", "secondary_acceptance_pass"]].copy()
    keep["timestamp"] = pd.to_datetime(keep["timestamp"], utc=True, errors="coerce")
    keep["strategy_id"] = keep["strategy_id"].astype(str)
    out["timestamp"] = pd.to_datetime(out["timestamp"], utc=True, errors="coerce")
    out["strategy_id"] = out["strategy_id"].astype(str)
    if "secondary_acceptance_pass" in out.columns:
        out = out.drop(columns=["secondary_acceptance_pass"])
    out = out.merge(keep, on=["timestamp", "strategy_id"], how="left")
    out["secondary_acceptance_pass"] = ~out["secondary_acceptance_pass"].eq(False)
    veto = (pd.to_numeric(out.get("multiplier"), errors="coerce").fillna(1.0) < 1.0) & ~out["secondary_acceptance_pass"]
    out.loc[veto, "multiplier"] = 1.0
    out.loc[veto, "selection_score"] = 0.0
    if "eligible_action" in out.columns:
        out.loc[veto, "eligible_action"] = False
    return out.sort_values(["timestamp", "strategy_id"])


def _apply_strategy_secondary_schedule_acceptance(
    schedule: pd.DataFrame,
    panel: pd.DataFrame,
    rules: dict[str, dict[str, Any]],
    *,
    default_pass: bool = False,
) -> pd.DataFrame:
    if schedule.empty:
        return schedule.copy()
    out = schedule.copy()
    rows = _secondary_acceptance_feature_rows(out, panel, include_labels=False)
    if rows.empty:
        out["secondary_acceptance_pass"] = bool(default_pass)
        if not bool(default_pass):
            veto = pd.to_numeric(out.get("multiplier"), errors="coerce").fillna(1.0) < 1.0
            out.loc[veto, "multiplier"] = 1.0
            out.loc[veto, "selection_score"] = 0.0
            if "eligible_action" in out.columns:
                out.loc[veto, "eligible_action"] = False
        return out.sort_values(["timestamp", "strategy_id"])
    rows["strategy_id"] = rows["strategy_id"].astype(str)
    rows["secondary_acceptance_pass"] = bool(default_pass)
    for strategy_id, rule in dict(rules).items():
        idx = rows["strategy_id"].eq(str(strategy_id))
        if not bool(idx.any()):
            continue
        rows.loc[idx, "secondary_acceptance_pass"] = _secondary_acceptance_mask(rows.loc[idx], rule).to_numpy(dtype=bool)
    keep = rows[["timestamp", "strategy_id", "secondary_acceptance_pass"]].copy()
    keep["timestamp"] = pd.to_datetime(keep["timestamp"], utc=True, errors="coerce")
    keep["strategy_id"] = keep["strategy_id"].astype(str)
    out["timestamp"] = pd.to_datetime(out["timestamp"], utc=True, errors="coerce")
    out["strategy_id"] = out["strategy_id"].astype(str)
    if "secondary_acceptance_pass" in out.columns:
        out = out.drop(columns=["secondary_acceptance_pass"])
    out = out.merge(keep, on=["timestamp", "strategy_id"], how="left")
    out["secondary_acceptance_pass"] = out["secondary_acceptance_pass"].eq(True) if bool(default_pass) is False else ~out["secondary_acceptance_pass"].eq(False)
    veto = (pd.to_numeric(out.get("multiplier"), errors="coerce").fillna(1.0) < 1.0) & ~out["secondary_acceptance_pass"]
    out.loc[veto, "multiplier"] = 1.0
    out.loc[veto, "selection_score"] = 0.0
    if "eligible_action" in out.columns:
        out.loc[veto, "eligible_action"] = False
    return out.sort_values(["timestamp", "strategy_id"])


_ACTION_SECONDARY_ACCEPTANCE_FEATURES = [
    "p_action_value_positive",
    "p_action_economic_positive",
    "p_action_positive",
    "cal_positive_rate",
    "cal_mean_delta_J",
    "cal_lcb_mean_delta_J",
    "cal_q10_delta_J",
    "cal_q25_delta_J",
    "pred_delta_J",
    "ranker_score",
]


def _action_secondary_acceptance_rows(
    schedule: pd.DataFrame,
    scored_actions: pd.DataFrame,
    *,
    include_labels: bool,
) -> pd.DataFrame:
    if schedule.empty or scored_actions.empty:
        return pd.DataFrame()
    sched = schedule.copy()
    actions = scored_actions.copy()
    for frame in (sched, actions):
        frame["timestamp"] = pd.to_datetime(frame["timestamp"], utc=True, errors="coerce")
        frame["strategy_id"] = frame["strategy_id"].astype(str)
        frame["multiplier"] = pd.to_numeric(frame.get("multiplier"), errors="coerce").fillna(1.0).astype(float)
    sched = sched.loc[sched["multiplier"] < 1.0].copy()
    if sched.empty:
        return pd.DataFrame()
    action_cols = [
        "timestamp",
        "strategy_id",
        "multiplier",
        "action_binds",
        *_ACTION_SECONDARY_ACCEPTANCE_FEATURES,
    ]
    if include_labels:
        action_cols.extend(["delta_full_J", "delta_immediate_J"])
    action_cols = [c for c in dict.fromkeys(action_cols) if c in actions.columns]
    rows = sched.merge(
        actions[action_cols].drop_duplicates(["timestamp", "strategy_id", "multiplier"]),
        on=["timestamp", "strategy_id", "multiplier"],
        how="left",
        suffixes=("", "_action"),
    )
    for col in ["action_binds", *_ACTION_SECONDARY_ACCEPTANCE_FEATURES]:
        raw = rows[col] if col in rows.columns else pd.Series(np.nan, index=rows.index)
        rows[col] = pd.to_numeric(raw, errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
    if include_labels:
        for col in ["delta_full_J", "delta_immediate_J"]:
            rows[col] = pd.to_numeric(rows.get(col), errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
    rows["action_secondary_acceptance_score"] = (
        (1.0 + rows["p_action_economic_positive"].clip(lower=0.0))
        * rows["p_action_value_positive"].clip(lower=0.0)
        * rows["p_action_positive"].clip(lower=0.0)
        * rows["cal_positive_rate"].clip(lower=0.0)
        * (1.0 + rows["ranker_score"].clip(lower=0.0))
    )
    return rows.sort_values(["timestamp", "strategy_id"])


def _choose_action_secondary_schedule_acceptance(
    schedule: pd.DataFrame,
    scored_actions: pd.DataFrame,
    *,
    threshold_holdout_frac: float = 0.0,
    min_precision: float = 1.0,
    max_intervention_rate: float = 0.15,
    require_no_harm: bool = True,
) -> tuple[dict[str, Any], dict[str, Any]]:
    thresholds: dict[str, Any] = {
        "enabled": False,
        "p_action_value_positive_min": np.inf,
        "p_action_economic_positive_min": np.inf,
        "p_action_positive_min": np.inf,
        "cal_positive_rate_min": np.inf,
        "cal_mean_delta_J_min": np.inf,
        "cal_lcb_mean_delta_J_min": -np.inf,
        "cal_q10_delta_J_min": -np.inf,
        "pred_delta_J_min": -np.inf,
        "ranker_score_min": -np.inf,
        "top_fraction": 0.0,
    }
    diag: dict[str, Any] = {
        "objective": 0.0,
        "train_interventions": 0,
        "train_intervention_rate": 0.0,
        "train_precision": 0.0,
        "train_delta_full_J_sum": 0.0,
        "train_positive_actions": 0,
        "train_groups": int(schedule[["timestamp", "strategy_id"]].drop_duplicates().shape[0]) if not schedule.empty else 0,
        "threshold_source": "no_op_no_action_secondary_acceptance_edge",
        "threshold_holdout_frac": float(threshold_holdout_frac),
        "require_no_harm": bool(require_no_harm),
    }
    rows = _action_secondary_acceptance_rows(schedule, scored_actions, include_labels=True)
    if rows.empty:
        return thresholds, diag
    rows = rows.loc[pd.to_numeric(rows.get("action_binds"), errors="coerce").fillna(0.0) > 0.0].copy()
    if rows.empty:
        return thresholds, diag
    total_group_count = int(schedule[["timestamp", "strategy_id"]].drop_duplicates().shape[0])
    rows = _chronological_threshold_holdout(rows, holdout_frac=float(threshold_holdout_frac))
    if rows.empty:
        return thresholds, diag
    group_count = max(total_group_count, int(rows[["timestamp", "strategy_id"]].drop_duplicates().shape[0]))
    diag["train_groups"] = int(group_count)

    def _grid(col: str, qs: tuple[float, ...], default: float) -> list[float]:
        vals = pd.to_numeric(rows.get(col), errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
        if vals.empty:
            return [float(default)]
        out = [float(default)] + [float(vals.quantile(q)) for q in qs]
        return sorted(set(float(x) for x in out if np.isfinite(x) or np.isinf(x)))

    best_objective = 0.0
    for value_pos_min in _grid("p_action_value_positive", (0.50, 0.75), 0.0):
        for econ_min in _grid("p_action_economic_positive", (0.50, 0.75, 0.90), 0.0):
            for action_min in _grid("p_action_positive", (0.50, 0.75), 0.0):
                for pos_rate_min in _grid("cal_positive_rate", (0.50, 0.75), 0.0):
                    for mean_min in _grid("cal_mean_delta_J", (0.50, 0.75), -np.inf):
                        for lcb_min in _grid("cal_lcb_mean_delta_J", (0.50, 0.75), -np.inf):
                            for q10_min in _grid("cal_q10_delta_J", (0.50, 0.75), -np.inf):
                                for pred_min in _grid("pred_delta_J", (0.50,), -np.inf):
                                    for ranker_min in _grid("ranker_score", (0.50,), -np.inf):
                                        base = rows.loc[
                                            (rows["p_action_value_positive"] >= float(value_pos_min))
                                            & (rows["p_action_economic_positive"] >= float(econ_min))
                                            & (rows["p_action_positive"] >= float(action_min))
                                            & (rows["cal_positive_rate"] >= float(pos_rate_min))
                                            & (rows["cal_mean_delta_J"] >= float(mean_min))
                                            & (rows["cal_lcb_mean_delta_J"] >= float(lcb_min))
                                            & (rows["cal_q10_delta_J"] >= float(q10_min))
                                            & (rows["pred_delta_J"] >= float(pred_min))
                                            & (rows["ranker_score"] >= float(ranker_min))
                                        ].copy()
                                        if base.empty:
                                            continue
                                        for top_fraction in (0.01, 0.025, 0.05, 0.075, 0.10, 0.15):
                                            n_top = max(1, int(np.ceil(group_count * float(top_fraction))))
                                            chosen = base.nlargest(min(n_top, len(base)), "action_secondary_acceptance_score").copy()
                                            interventions = int(len(chosen))
                                            if interventions <= 0:
                                                continue
                                            rate = float(interventions / max(group_count, 1))
                                            if rate > float(max_intervention_rate):
                                                continue
                                            realized = pd.to_numeric(chosen["delta_full_J"], errors="coerce").fillna(0.0)
                                            total = float(realized.sum())
                                            positives = int((realized > MATERIAL_DELTA_EPS).sum())
                                            precision = float(positives / max(interventions, 1))
                                            harmful = float(realized.clip(upper=0.0).abs().sum())
                                            if positives <= 0 or total <= 0.0 or precision < float(min_precision):
                                                continue
                                            if bool(require_no_harm) and harmful > 1e-9:
                                                continue
                                            objective = (total - 5.0 * harmful) * precision / np.sqrt(max(interventions, 1))
                                            if objective > best_objective:
                                                best_objective = float(objective)
                                                thresholds = {
                                                    "enabled": True,
                                                    "p_action_value_positive_min": float(value_pos_min),
                                                    "p_action_economic_positive_min": float(econ_min),
                                                    "p_action_positive_min": float(action_min),
                                                    "cal_positive_rate_min": float(pos_rate_min),
                                                    "cal_mean_delta_J_min": float(mean_min),
                                                    "cal_lcb_mean_delta_J_min": float(lcb_min),
                                                    "cal_q10_delta_J_min": float(q10_min),
                                                    "pred_delta_J_min": float(pred_min),
                                                    "ranker_score_min": float(ranker_min),
                                                    "top_fraction": float(top_fraction),
                                                }
                                                diag = {
                                                    "objective": float(objective),
                                                    "train_interventions": interventions,
                                                    "train_intervention_rate": rate,
                                                    "train_precision": precision,
                                                    "train_delta_full_J_sum": total,
                                                    "train_positive_actions": positives,
                                                    "train_groups": int(group_count),
                                                    "threshold_source": "holdout_action_secondary_acceptance_grid"
                                                    if float(threshold_holdout_frac) > 0.0
                                                    else "training_action_secondary_acceptance_grid",
                                                    "threshold_holdout_frac": float(threshold_holdout_frac),
                                                    "false_selection_penalty": harmful,
                                                    "require_no_harm": bool(require_no_harm),
                                                }
    return thresholds, diag


def _apply_action_secondary_schedule_acceptance(
    schedule: pd.DataFrame,
    scored_actions: pd.DataFrame,
    thresholds: dict[str, Any],
    *,
    default_pass: bool = False,
) -> pd.DataFrame:
    if schedule.empty:
        return schedule.copy()
    out = schedule.copy()
    if not bool(thresholds.get("enabled", False)):
        out["action_secondary_acceptance_pass"] = bool(default_pass)
        if not bool(default_pass):
            veto = pd.to_numeric(out.get("multiplier"), errors="coerce").fillna(1.0) < 1.0
            out.loc[veto, "multiplier"] = 1.0
            out.loc[veto, "selection_score"] = 0.0
            if "eligible_action" in out.columns:
                out.loc[veto, "eligible_action"] = False
        return out.sort_values(["timestamp", "strategy_id"])
    rows = _action_secondary_acceptance_rows(out, scored_actions, include_labels=False)
    if rows.empty:
        out["action_secondary_acceptance_pass"] = bool(default_pass)
        if not bool(default_pass):
            veto = pd.to_numeric(out.get("multiplier"), errors="coerce").fillna(1.0) < 1.0
            out.loc[veto, "multiplier"] = 1.0
            out.loc[veto, "selection_score"] = 0.0
            if "eligible_action" in out.columns:
                out.loc[veto, "eligible_action"] = False
        return out.sort_values(["timestamp", "strategy_id"])
    keep_mask = (
        (rows["p_action_value_positive"] >= float(thresholds.get("p_action_value_positive_min", -np.inf)))
        & (rows["p_action_economic_positive"] >= float(thresholds.get("p_action_economic_positive_min", np.inf)))
        & (rows["p_action_positive"] >= float(thresholds.get("p_action_positive_min", np.inf)))
        & (rows["cal_positive_rate"] >= float(thresholds.get("cal_positive_rate_min", np.inf)))
        & (rows["cal_mean_delta_J"] >= float(thresholds.get("cal_mean_delta_J_min", np.inf)))
        & (rows["cal_lcb_mean_delta_J"] >= float(thresholds.get("cal_lcb_mean_delta_J_min", -np.inf)))
        & (rows["cal_q10_delta_J"] >= float(thresholds.get("cal_q10_delta_J_min", -np.inf)))
        & (rows["pred_delta_J"] >= float(thresholds.get("pred_delta_J_min", -np.inf)))
        & (rows["ranker_score"] >= float(thresholds.get("ranker_score_min", -np.inf)))
    )
    rows = rows.copy()
    rows["action_secondary_acceptance_pass"] = keep_mask.to_numpy(dtype=bool)
    top_fraction = float(thresholds.get("top_fraction", 0.0))
    if top_fraction > 0.0 and bool(rows["action_secondary_acceptance_pass"].any()):
        group_count = int(out[["timestamp", "strategy_id"]].drop_duplicates().shape[0])
        n_top = max(1, int(np.ceil(group_count * min(max(top_fraction, 0.0), 1.0))))
        selected_idx = rows.loc[rows["action_secondary_acceptance_pass"]].nlargest(
            min(n_top, int(rows["action_secondary_acceptance_pass"].sum())),
            "action_secondary_acceptance_score",
        ).index
        rows["action_secondary_acceptance_pass"] = False
        rows.loc[list(selected_idx), "action_secondary_acceptance_pass"] = True
    keep = rows[["timestamp", "strategy_id", "action_secondary_acceptance_pass"]].copy()
    keep["timestamp"] = pd.to_datetime(keep["timestamp"], utc=True, errors="coerce")
    keep["strategy_id"] = keep["strategy_id"].astype(str)
    out["timestamp"] = pd.to_datetime(out["timestamp"], utc=True, errors="coerce")
    out["strategy_id"] = out["strategy_id"].astype(str)
    out = out.drop(columns=["action_secondary_acceptance_pass"], errors="ignore").merge(keep, on=["timestamp", "strategy_id"], how="left")
    out["action_secondary_acceptance_pass"] = (
        out["action_secondary_acceptance_pass"].eq(True)
        if bool(default_pass) is False
        else ~out["action_secondary_acceptance_pass"].eq(False)
    )
    veto = (pd.to_numeric(out.get("multiplier"), errors="coerce").fillna(1.0) < 1.0) & ~out["action_secondary_acceptance_pass"]
    out.loc[veto, "multiplier"] = 1.0
    out.loc[veto, "selection_score"] = 0.0
    if "eligible_action" in out.columns:
        out.loc[veto, "eligible_action"] = False
    return out.sort_values(["timestamp", "strategy_id"])


def _rank_calibrated_value_schedule(
    scored_actions: pd.DataFrame,
    thresholds: dict[str, Any],
) -> pd.DataFrame:
    actions = scored_actions.copy()
    if actions.empty:
        return pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action"])
    actions["timestamp"] = pd.to_datetime(actions["timestamp"], utc=True, errors="coerce")
    actions["strategy_id"] = actions["strategy_id"].astype(str)
    actions["multiplier"] = pd.to_numeric(actions.get("multiplier"), errors="coerce").fillna(1.0).astype(float)
    base = actions[["timestamp", "strategy_id"]].drop_duplicates().copy()
    base["multiplier"] = 1.0
    base["selection_score"] = 0.0
    base["eligible_action"] = False
    if not bool(thresholds.get("enabled", False)):
        return base.sort_values(["timestamp", "strategy_id"]).reset_index(drop=True)

    score_col = str(thresholds.get("score_col", "cal_mean_delta_J"))
    for col in [
        "action_binds",
        "group_can_bind",
        "strategy_rank_q90",
        "strategy_open_count",
        "pred_delta_J",
        "cal_mean_delta_J",
        "cal_lcb_mean_delta_J",
        "cal_q10_delta_J",
        "cal_q25_delta_J",
        "cal_positive_rate",
        "p_action_positive",
        "p_action_value_positive",
        "p_action_economic_positive",
        "ranker_score",
        score_col,
    ]:
        if col in actions.columns:
            actions[col] = pd.to_numeric(actions[col], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
        else:
            actions[col] = 0.0
    candidates = actions.loc[
        (actions["multiplier"] < 1.0)
        & (actions["action_binds"] > 0.0)
        & (actions["group_can_bind"] > 0.0)
        & (actions["strategy_rank_q90"] >= float(thresholds.get("strategy_rank_q90_min", 0.70)))
        & (actions["strategy_open_count"] <= float(thresholds.get("strategy_open_count_max", 2.0)))
        & (actions[score_col] >= float(thresholds.get("score_min", -np.inf)))
        & (actions["p_action_positive"] >= float(thresholds.get("p_action_positive_min", -np.inf)))
        & (actions["p_action_value_positive"] >= float(thresholds.get("p_action_value_positive_min", -np.inf)))
        & (actions["p_action_economic_positive"] >= float(thresholds.get("p_action_economic_positive_min", -np.inf)))
        & (actions["cal_positive_rate"] >= float(thresholds.get("cal_positive_rate_min", -np.inf)))
    ].copy()
    if candidates.empty:
        return base.sort_values(["timestamp", "strategy_id"]).reset_index(drop=True)
    candidates["rank_calibrated_value_score"] = pd.to_numeric(candidates[score_col], errors="coerce").fillna(0.0)
    chosen = (
        candidates.sort_values(
            ["timestamp", "strategy_id", "rank_calibrated_value_score", "pred_delta_J", "multiplier"],
            ascending=[True, True, False, False, False],
        )
        .drop_duplicates(["timestamp", "strategy_id"])
        .copy()
    )
    top_fraction = float(thresholds.get("top_fraction", 0.0))
    if top_fraction > 0.0:
        group_count = int(base[["timestamp", "strategy_id"]].drop_duplicates().shape[0])
        n_top = max(1, int(np.ceil(group_count * min(max(top_fraction, 0.0), 1.0))))
        chosen = chosen.nlargest(min(n_top, len(chosen)), "rank_calibrated_value_score").copy()
    keep = [
        c
        for c in [
            "timestamp",
            "strategy_id",
            "multiplier",
            "rank_calibrated_value_score",
            "p_intervene",
            "stage1_cal_positive_rate",
            "stage1_cal_mean_gain",
            "stage1_cal_lcb_mean_gain",
            "pred_delta_J",
            "pred_immediate_J",
            "pred_capacity_J",
            "cal_mean_delta_J",
            "cal_lcb_mean_delta_J",
            "cal_q10_delta_J",
            "cal_q25_delta_J",
            "cal_positive_rate",
            "p_action_value_positive",
            "p_action_positive",
            "p_action_economic_positive",
            "ranker_score",
        ]
        if c in chosen.columns
    ]
    chosen = chosen[keep].copy()
    chosen["selection_score"] = pd.to_numeric(chosen["rank_calibrated_value_score"], errors="coerce").fillna(0.0)
    chosen["eligible_action"] = True
    out = base.merge(chosen, on=["timestamp", "strategy_id"], how="left", suffixes=("_base", ""))
    out["multiplier"] = pd.to_numeric(out.get("multiplier"), errors="coerce").fillna(1.0)
    out["selection_score"] = pd.to_numeric(out.get("selection_score"), errors="coerce").fillna(0.0)
    out["eligible_action"] = out.get("eligible_action", False).fillna(False).astype(bool)
    for col in ["multiplier_base", "selection_score_base", "eligible_action_base"]:
        if col in out.columns:
            out = out.drop(columns=[col])
    return out.sort_values(["timestamp", "strategy_id"]).reset_index(drop=True)


def _choose_rank_calibrated_value_gate(
    scored_actions: pd.DataFrame,
    *,
    threshold_holdout_frac: float = 0.0,
    min_precision: float = 0.90,
    max_intervention_rate: float = 0.12,
    require_no_harm: bool = True,
) -> tuple[dict[str, Any], dict[str, Any]]:
    thresholds: dict[str, Any] = {
        "enabled": False,
        "score_col": "cal_mean_delta_J",
        "score_min": np.inf,
        "top_fraction": 0.0,
        "strategy_rank_q90_min": 0.70,
        "strategy_open_count_max": 2.0,
        "p_action_positive_min": -np.inf,
        "p_action_value_positive_min": -np.inf,
        "p_action_economic_positive_min": -np.inf,
        "cal_positive_rate_min": -np.inf,
    }
    diag: dict[str, Any] = {
        "objective": 0.0,
        "train_interventions": 0,
        "train_intervention_rate": 0.0,
        "train_precision": 0.0,
        "train_delta_full_J_sum": 0.0,
        "train_positive_actions": 0,
        "train_groups": 0,
        "threshold_source": "no_op_no_rank_calibrated_value_edge",
        "threshold_holdout_frac": float(threshold_holdout_frac),
        "require_no_harm": bool(require_no_harm),
    }
    actions = scored_actions.copy()
    if actions.empty:
        return thresholds, diag
    actions["timestamp"] = pd.to_datetime(actions["timestamp"], utc=True, errors="coerce")
    actions["strategy_id"] = actions["strategy_id"].astype(str)
    total_group_count = int(actions[["timestamp", "strategy_id"]].drop_duplicates().shape[0])
    diag["train_groups"] = int(total_group_count)
    for col in [
        "multiplier",
        "action_binds",
        "group_can_bind",
        "strategy_rank_q90",
        "strategy_open_count",
        "delta_full_J",
        "cal_mean_delta_J",
        "cal_lcb_mean_delta_J",
        "cal_q10_delta_J",
        "cal_q25_delta_J",
        "pred_delta_J",
        "ranker_score",
        "p_action_positive",
        "p_action_value_positive",
        "p_action_economic_positive",
        "cal_positive_rate",
    ]:
        if col in actions.columns:
            actions[col] = pd.to_numeric(actions[col], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
        else:
            actions[col] = 0.0
    work = actions.loc[
        (actions["multiplier"] < 1.0)
        & (actions["action_binds"] > 0.0)
        & (actions["group_can_bind"] > 0.0)
        & (actions["strategy_rank_q90"] >= 0.70)
        & (actions["strategy_open_count"] <= 2.0)
    ].copy()
    if work.empty:
        return thresholds, diag
    work = _chronological_threshold_holdout(work, holdout_frac=float(threshold_holdout_frac))
    if work.empty:
        return thresholds, diag
    group_count = max(total_group_count, int(work[["timestamp", "strategy_id"]].drop_duplicates().shape[0]))
    diag["train_groups"] = int(group_count)

    def _grid(col: str, qs: tuple[float, ...], default: float) -> list[float]:
        vals = pd.to_numeric(work.get(col), errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
        if vals.empty:
            return [float(default)]
        out = [float(default)] + [float(vals.quantile(q)) for q in qs]
        return sorted(set(float(x) for x in out if np.isfinite(x) or np.isinf(x)))

    score_cols = [
        c
        for c in ["cal_mean_delta_J", "cal_lcb_mean_delta_J", "cal_q25_delta_J", "cal_q10_delta_J"]
        if c in work.columns
    ]
    min_interventions = max(6, int(np.ceil(0.03 * group_count)))
    top_fractions = (0.05, 0.075, 0.10, 0.15, 0.20)
    best_objective = 0.0
    for score_col in score_cols:
        score_grid = _grid(score_col, (0.50, 0.65, 0.75, 0.85), -np.inf)
        action_pos_grid = _grid("p_action_positive", (0.50,), -np.inf)
        value_pos_grid = _grid("p_action_value_positive", (0.50,), -np.inf)
        econ_pos_grid = _grid("p_action_economic_positive", (0.50,), -np.inf)
        cal_pos_grid = _grid("cal_positive_rate", (0.50,), -np.inf)
        for score_min in score_grid:
            for action_pos_min in action_pos_grid:
                for value_pos_min in value_pos_grid:
                    for econ_pos_min in econ_pos_grid:
                        for cal_pos_min in cal_pos_grid:
                            base = work.loc[
                                (work[score_col] >= float(score_min))
                                & (work["p_action_positive"] >= float(action_pos_min))
                                & (work["p_action_value_positive"] >= float(value_pos_min))
                                & (work["p_action_economic_positive"] >= float(econ_pos_min))
                                & (work["cal_positive_rate"] >= float(cal_pos_min))
                            ].copy()
                            if base.empty:
                                continue
                            base["_rank_value_score"] = pd.to_numeric(base[score_col], errors="coerce").fillna(0.0)
                            chosen_by_group = (
                                base.sort_values(
                                    ["timestamp", "strategy_id", "_rank_value_score", "pred_delta_J", "multiplier"],
                                    ascending=[True, True, False, False, False],
                                )
                                .drop_duplicates(["timestamp", "strategy_id"])
                                .copy()
                            )
                            for top_fraction in top_fractions:
                                n_top = max(1, int(np.ceil(group_count * float(top_fraction))))
                                chosen = chosen_by_group.nlargest(min(n_top, len(chosen_by_group)), "_rank_value_score")
                                interventions = int(len(chosen))
                                if interventions < min_interventions:
                                    continue
                                rate = float(interventions / max(group_count, 1))
                                if rate > float(max_intervention_rate):
                                    continue
                                realized = pd.to_numeric(chosen["delta_full_J"], errors="coerce").fillna(0.0)
                                total = float(realized.sum())
                                positives = int((realized > MATERIAL_DELTA_EPS).sum())
                                precision = float(positives / max(interventions, 1))
                                harmful = float(realized.clip(upper=0.0).abs().sum())
                                if positives <= 0 or total <= 0.0 or precision < float(min_precision):
                                    continue
                                if bool(require_no_harm) and harmful > 1e-9:
                                    continue
                                objective = (total - 6.0 * harmful) * precision / np.sqrt(max(interventions, 1))
                                if objective > best_objective:
                                    best_objective = float(objective)
                                    thresholds = {
                                        "enabled": True,
                                        "score_col": str(score_col),
                                        "score_min": float(score_min),
                                        "top_fraction": float(top_fraction),
                                        "strategy_rank_q90_min": 0.70,
                                        "strategy_open_count_max": 2.0,
                                        "p_action_positive_min": float(action_pos_min),
                                        "p_action_value_positive_min": float(value_pos_min),
                                        "p_action_economic_positive_min": float(econ_pos_min),
                                        "cal_positive_rate_min": float(cal_pos_min),
                                    }
                                    diag = {
                                        "objective": float(objective),
                                        "train_interventions": interventions,
                                        "train_intervention_rate": rate,
                                        "train_precision": precision,
                                        "train_delta_full_J_sum": total,
                                        "train_positive_actions": positives,
                                        "train_groups": int(group_count),
                                        "threshold_source": "holdout_rank_calibrated_value_grid"
                                        if float(threshold_holdout_frac) > 0.0
                                        else "training_rank_calibrated_value_grid",
                                        "threshold_holdout_frac": float(threshold_holdout_frac),
                                        "false_selection_penalty": harmful,
                                        "require_no_harm": bool(require_no_harm),
                                    }
    return thresholds, diag


def _direct_fixed_zero_action_schedule(scored_actions: pd.DataFrame) -> pd.DataFrame:
    if scored_actions.empty:
        return pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action"])
    work = scored_actions.copy()
    work["timestamp"] = pd.to_datetime(work["timestamp"], utc=True, errors="coerce")
    work["strategy_id"] = work["strategy_id"].astype(str)
    work["multiplier"] = pd.to_numeric(work.get("multiplier"), errors="coerce").fillna(1.0).astype(float)
    work = work.loc[np.isclose(work["multiplier"], 0.0) & work["timestamp"].notna()].copy()
    if work.empty:
        return pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action"])
    for col in ["action_binds", *_ACTION_SECONDARY_ACCEPTANCE_FEATURES]:
        raw = work[col] if col in work.columns else pd.Series(np.nan, index=work.index)
        work[col] = pd.to_numeric(raw, errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
    work = work.loc[work["action_binds"] > 0.0].copy()
    if work.empty:
        return pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action"])
    work["action_secondary_acceptance_score"] = (
        (1.0 + work["p_action_economic_positive"].clip(lower=0.0))
        * work["p_action_value_positive"].clip(lower=0.0)
        * work["p_action_positive"].clip(lower=0.0)
        * work["cal_positive_rate"].clip(lower=0.0)
        * (1.0 + work["ranker_score"].clip(lower=0.0))
    )
    work["selection_score"] = work["action_secondary_acceptance_score"].astype(float)
    work["eligible_action"] = True
    keep = ["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action", "action_secondary_acceptance_score"]
    return work[[c for c in keep if c in work.columns]].drop_duplicates(["timestamp", "strategy_id", "multiplier"]).sort_values(
        ["timestamp", "strategy_id"]
    )


def _direct_zero_half_action_schedule(scored_actions: pd.DataFrame) -> pd.DataFrame:
    if scored_actions.empty:
        return pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action"])
    work = scored_actions.copy()
    work["timestamp"] = pd.to_datetime(work["timestamp"], utc=True, errors="coerce")
    work["strategy_id"] = work["strategy_id"].astype(str)
    work["multiplier"] = pd.to_numeric(work.get("multiplier"), errors="coerce").fillna(1.0).astype(float)
    work = work.loc[work["timestamp"].notna() & work["multiplier"].isin([0.0, 0.5])].copy()
    if work.empty:
        return pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action"])
    for col in ["action_binds", *_ACTION_SECONDARY_ACCEPTANCE_FEATURES]:
        raw = work[col] if col in work.columns else pd.Series(np.nan, index=work.index)
        work[col] = pd.to_numeric(raw, errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
    work = work.loc[work["action_binds"] > 0.0].copy()
    if work.empty:
        return pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action"])
    work["action_secondary_acceptance_score"] = (
        (1.0 + work["p_action_economic_positive"].clip(lower=0.0))
        * work["p_action_value_positive"].clip(lower=0.0)
        * work["p_action_positive"].clip(lower=0.0)
        * work["cal_positive_rate"].clip(lower=0.0)
        * (1.0 + work["ranker_score"].clip(lower=0.0))
    )
    work = work.sort_values(
        ["timestamp", "strategy_id", "action_secondary_acceptance_score", "multiplier"],
        ascending=[True, True, False, True],
    ).drop_duplicates(["timestamp", "strategy_id"])
    work["selection_score"] = work["action_secondary_acceptance_score"].astype(float)
    work["eligible_action"] = True
    keep = ["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action", "action_secondary_acceptance_score"]
    return work[[c for c in keep if c in work.columns]].sort_values(["timestamp", "strategy_id"])


def _zero_cut_classifier_feature_cols(rows: pd.DataFrame, max_features: int = 96) -> list[str]:
    exclude = {
        "timestamp",
        "strategy_id",
        "fold_id",
        "split",
        "multiplier",
        "delta_full_J",
        "delta_immediate_J",
        "delta_full_net_pnl",
        "delta_full_cost_pnl",
        "delta_full_turnover",
        "delta_full_J_per_notional",
        "delta_immediate_J_per_notional",
        "zero_cut_target",
        "zero_cut_trainable",
    }
    exclude.update(GROUP_LABEL_COLUMNS)
    preferred = [
        *COMPACT_STAGE1_FEATURES,
        "strategy_code",
        "projected_removed_trade_count",
        "projected_action_strength",
        "projected_notional_removed",
        "projected_notional_removed_to_wallet",
        "projected_notional_removed_to_open_notional",
        "projected_notional_removed_to_remaining_capital",
        "projected_removed_trade_share_strategy",
        "projected_removed_trade_share_timestamp",
    ]
    cols: list[str] = []
    for col in preferred:
        if col in cols:
            continue
        if col in rows.columns and col not in exclude and pd.api.types.is_numeric_dtype(rows[col]):
            vals = pd.to_numeric(rows[col], errors="coerce").replace([np.inf, -np.inf], np.nan)
            if vals.notna().sum() > 0 and vals.nunique(dropna=True) > 1:
                cols.append(col)
    for col in _numeric_cols(rows, exclude):
        if col not in cols:
            vals = pd.to_numeric(rows[col], errors="coerce").replace([np.inf, -np.inf], np.nan)
            if vals.notna().sum() > 0 and vals.nunique(dropna=True) > 1:
                cols.append(col)
    return cols[: int(max_features)]


def _zero_cut_classifier_matrix(rows: pd.DataFrame, feature_cols: list[str], medians: pd.Series | None = None) -> tuple[pd.DataFrame, pd.Series]:
    x = rows[feature_cols].apply(pd.to_numeric, errors="coerce").replace([np.inf, -np.inf], np.nan)
    if medians is None:
        medians = x.median(numeric_only=True).replace([np.inf, -np.inf], np.nan).fillna(0.0)
    return x.fillna(medians).astype(np.float32), medians


def _zero_cut_action_rows_for_classifier(panel: pd.DataFrame, *, material_gain: float = 50.0) -> pd.DataFrame:
    rows = panel.copy()
    rows["timestamp"] = pd.to_datetime(rows["timestamp"], utc=True, errors="coerce")
    rows["strategy_id"] = rows["strategy_id"].astype(str)
    rows["multiplier"] = pd.to_numeric(rows.get("multiplier"), errors="coerce").fillna(1.0).astype(float)
    rows = rows.loc[rows["timestamp"].notna() & np.isclose(rows["multiplier"], 0.0)].copy()
    if rows.empty:
        return rows
    rows["action_binds"] = pd.to_numeric(rows.get("action_binds"), errors="coerce").fillna(0.0)
    rows = rows.loc[rows["action_binds"] > 0.0].copy()
    if rows.empty:
        return rows
    rows["delta_full_J"] = pd.to_numeric(rows.get("delta_full_J"), errors="coerce").fillna(0.0)
    rows["zero_cut_target"] = rows["delta_full_J"].ge(float(material_gain))
    rows["zero_cut_trainable"] = rows["delta_full_J"].ge(float(material_gain)) | rows["delta_full_J"].le(-float(material_gain))
    return rows.sort_values(["timestamp", "strategy_id"])


def _high_value_zero_cut_classifier_schedule(
    train_panel: pd.DataFrame,
    eval_panel: pd.DataFrame,
    *,
    material_gain: float = 50.0,
    top_fraction: float = 0.01,
    seed: int = 1729,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    train_rows = _zero_cut_action_rows_for_classifier(train_panel, material_gain=float(material_gain))
    eval_rows = _zero_cut_action_rows_for_classifier(eval_panel, material_gain=float(material_gain))
    diag: dict[str, Any] = {
        "enabled": False,
        "train_rows": int(len(train_rows)),
        "eval_rows": int(len(eval_rows)),
        "train_positive_rows": int(train_rows.get("zero_cut_target", pd.Series(dtype=bool)).sum()) if not train_rows.empty else 0,
        "top_fraction": float(top_fraction),
        "material_gain": float(material_gain),
        "selected_eval_rows": 0,
        "threshold_source": "no_op_insufficient_zero_cut_classifier_data",
    }
    empty = pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action"])
    if train_rows.empty or eval_rows.empty:
        return empty, diag
    strategy_categories = sorted(set(train_rows["strategy_id"].astype(str)).union(set(eval_rows["strategy_id"].astype(str))))
    strategy_map = {strategy: idx for idx, strategy in enumerate(strategy_categories)}
    train_rows["strategy_code"] = train_rows["strategy_id"].astype(str).map(strategy_map).fillna(-1).astype(float)
    eval_rows["strategy_code"] = eval_rows["strategy_id"].astype(str).map(strategy_map).fillna(-1).astype(float)
    fit_rows = train_rows.loc[train_rows["zero_cut_trainable"].eq(True)].copy()
    if len(fit_rows) < 30 or fit_rows["zero_cut_target"].nunique() < 2:
        return empty, diag
    initial_feature_cols = _zero_cut_classifier_feature_cols(fit_rows, max_features=96)
    if len(initial_feature_cols) < 5:
        return empty, diag
    y = fit_rows["zero_cut_target"].astype(int).to_numpy()
    delta = pd.to_numeric(fit_rows["delta_full_J"], errors="coerce").fillna(0.0).to_numpy(dtype=float)
    weights = np.ones(len(fit_rows), dtype=float)
    pos = y.astype(bool)
    pos_scale = max(float(np.nanmedian(np.abs(delta[pos]))) if np.any(pos) else 1.0, 1.0)
    neg_scale = max(float(np.nanmedian(np.abs(delta[~pos]))) if np.any(~pos) else 1.0, 1.0)
    weights[pos] *= 1.0 + 0.25 * np.clip(delta[pos] / pos_scale, 0.0, 10.0)
    weights[~pos] *= 1.0 + 0.75 * np.clip(np.abs(np.minimum(delta[~pos], 0.0)) / neg_scale, 0.0, 20.0)
    try:
        from lightgbm import LGBMClassifier

        selector: Any = LGBMClassifier(
            objective="binary",
            n_estimators=140,
            learning_rate=0.035,
            num_leaves=15,
            max_depth=4,
            min_child_samples=max(20, int(0.03 * len(fit_rows))),
            subsample=0.85,
            colsample_bytree=0.85,
            reg_alpha=0.1,
            reg_lambda=2.0,
            scale_pos_weight=float(max((len(y) - y.sum()) / max(y.sum(), 1), 1.0)),
            **_lgbm_deterministic_kwargs(seed),
            verbose=-1,
        )
        x_select, select_medians = _zero_cut_classifier_matrix(fit_rows, initial_feature_cols)
        selector.fit(x_select, y, sample_weight=weights)
        importances = np.asarray(getattr(selector, "feature_importances_", np.zeros(len(initial_feature_cols))), dtype=float)
        order = np.argsort(-importances)
        feature_cols = [initial_feature_cols[i] for i in order[:48] if importances[i] > 0.0]
        if len(feature_cols) < min(10, len(initial_feature_cols)):
            feature_cols = [initial_feature_cols[i] for i in order[:48]]
        clf: Any = LGBMClassifier(
            objective="binary",
            n_estimators=180,
            learning_rate=0.035,
            num_leaves=15,
            max_depth=4,
            min_child_samples=max(20, int(0.03 * len(fit_rows))),
            subsample=0.85,
            colsample_bytree=0.85,
            reg_alpha=0.1,
            reg_lambda=2.0,
            scale_pos_weight=float(max((len(y) - y.sum()) / max(y.sum(), 1), 1.0)),
            **_lgbm_deterministic_kwargs(seed + 101),
            verbose=-1,
        )
        x_train, medians = _zero_cut_classifier_matrix(fit_rows, feature_cols)
        clf.fit(x_train, y, sample_weight=weights)
        x_eval, _ = _zero_cut_classifier_matrix(eval_rows, feature_cols, medians)
        score = clf.predict_proba(x_eval)[:, 1]
    except Exception:
        return empty, {**diag, "threshold_source": "no_op_zero_cut_classifier_fit_failed"}
    scored = eval_rows[["timestamp", "strategy_id", "multiplier"]].copy()
    scored["selection_score"] = score.astype(float)
    scored["eligible_action"] = True
    n_top = max(1, int(np.ceil(len(scored) * max(min(float(top_fraction), 1.0), 0.0))))
    selected = scored.nlargest(min(n_top, len(scored)), "selection_score").copy()
    selected["zero_cut_classifier_score"] = selected["selection_score"].astype(float)
    diag.update(
        {
            "enabled": True,
            "train_fit_rows": int(len(fit_rows)),
            "train_positive_rows": int(y.sum()),
            "initial_feature_count": int(len(initial_feature_cols)),
            "feature_count": int(len(feature_cols)),
            "selected_eval_rows": int(len(selected)),
            "threshold_source": "fold_local_high_value_zero_cut_classifier_top_fraction",
        }
    )
    return selected.sort_values(["timestamp", "strategy_id"]), diag


def _head_specific_high_value_zero_cut_classifier_schedule(
    train_panel: pd.DataFrame,
    eval_panel: pd.DataFrame,
    *,
    material_gain: float = 50.0,
    top_fraction: float = 0.05,
    seed: int = 1729,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Fit the C3el high-value zero-cut classifier independently per head."""
    empty = pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action"])
    if train_panel.empty or eval_panel.empty or "strategy_id" not in train_panel.columns or "strategy_id" not in eval_panel.columns:
        return empty, {
            "enabled": False,
            "scope": "head_specific",
            "heads": [],
            "selected_eval_rows": 0,
            "threshold_source": "no_op_empty_panel_or_missing_strategy_id",
        }
    train_heads = train_panel["strategy_id"].astype(str).map(_strategy_head)
    eval_heads = eval_panel["strategy_id"].astype(str).map(_strategy_head)
    pieces: list[pd.DataFrame] = []
    head_records: list[dict[str, Any]] = []
    for idx, head in enumerate(HEAD_PREFIXES):
        train_head = train_panel.loc[train_heads.eq(head)].copy()
        eval_head = eval_panel.loc[eval_heads.eq(head)].copy()
        selected, diag = _high_value_zero_cut_classifier_schedule(
            train_head,
            eval_head,
            material_gain=float(material_gain),
            top_fraction=float(top_fraction),
            seed=int(seed) + 1009 * (idx + 1),
        )
        diag = dict(diag)
        diag["head"] = head
        diag["scope"] = "head_specific"
        head_records.append(_json_safe(diag))
        if selected.empty:
            continue
        selected = selected.copy()
        selected["head_specific_c3el_head"] = head
        selected["head_specific_c3el_enabled"] = bool(diag.get("enabled", False))
        selected["head_specific_c3el_top_fraction"] = float(top_fraction)
        pieces.append(selected)
    if not pieces:
        return empty, {
            "enabled": False,
            "scope": "head_specific",
            "heads": head_records,
            "selected_eval_rows": 0,
            "threshold_source": "no_op_no_head_selected_rows",
        }
    out = pd.concat(pieces, ignore_index=False, sort=False).sort_values(["timestamp", "strategy_id"])
    return out, {
        "enabled": True,
        "scope": "head_specific",
        "heads": head_records,
        "selected_eval_rows": int(len(out)),
        "head_selected_eval_rows": {head: int((out["head_specific_c3el_head"].astype(str) == head).sum()) for head in HEAD_PREFIXES},
        "top_fraction": float(top_fraction),
        "material_gain": float(material_gain),
        "threshold_source": "fold_local_head_specific_high_value_zero_cut_classifier_top_fraction",
    }


def _group_opportunity_classifier_feature_cols(rows: pd.DataFrame, max_features: int = 96) -> list[str]:
    exclude = {
        "timestamp",
        "strategy_id",
        "fold_id",
        "split",
        "multiplier",
        "group_opportunity_target",
        "group_opportunity_trainable",
        "missed_oracle_target",
        "missed_oracle_trainable",
    }
    exclude.update(GROUP_LABEL_COLUMNS)
    preferred = [
        *COMPACT_STAGE1_FEATURES,
        *STAGE1_SAFETY_FEATURES,
        "strategy_code",
    ]
    cols: list[str] = []
    for col in preferred:
        if col in cols:
            continue
        if col in rows.columns and col not in exclude and pd.api.types.is_numeric_dtype(rows[col]):
            vals = pd.to_numeric(rows[col], errors="coerce").replace([np.inf, -np.inf], np.nan)
            if vals.notna().sum() > 0 and vals.nunique(dropna=True) > 1:
                cols.append(col)
    for col in _numeric_cols(rows, exclude):
        if col not in cols:
            vals = pd.to_numeric(rows[col], errors="coerce").replace([np.inf, -np.inf], np.nan)
            if vals.notna().sum() > 0 and vals.nunique(dropna=True) > 1:
                cols.append(col)
    return cols[: int(max_features)]


def _group_opportunity_classifier_matrix(rows: pd.DataFrame, feature_cols: list[str], medians: pd.Series | None = None) -> tuple[pd.DataFrame, pd.Series]:
    x = rows[feature_cols].apply(pd.to_numeric, errors="coerce").replace([np.inf, -np.inf], np.nan)
    if medians is None:
        medians = x.median(numeric_only=True).replace([np.inf, -np.inf], np.nan).fillna(0.0)
    return x.fillna(medians).astype(np.float32), medians


def _group_rows_for_opportunity_classifier(
    panel: pd.DataFrame,
    *,
    material_gain: float = 50.0,
    material_margin: float = 25.0,
    min_gain_per_notional: float = 0.001,
    min_margin_per_notional: float = 0.0005,
    min_rank_q90: float = 0.70,
) -> pd.DataFrame:
    rows = panel.loc[np.isclose(pd.to_numeric(panel.get("multiplier"), errors="coerce").fillna(np.nan), 1.0)].copy()
    if rows.empty:
        return rows
    rows["timestamp"] = pd.to_datetime(rows["timestamp"], utc=True, errors="coerce")
    rows["strategy_id"] = rows["strategy_id"].astype(str)
    rows = rows.loc[rows["timestamp"].notna()].copy()
    if rows.empty:
        return rows
    rows["group_can_bind"] = pd.to_numeric(rows.get("group_can_bind"), errors="coerce").fillna(0.0)
    rows["strategy_rank_q90"] = pd.to_numeric(rows.get("strategy_rank_q90"), errors="coerce").fillna(0.0)
    rows = rows.loc[(rows["group_can_bind"] > 0.0) & (rows["strategy_rank_q90"] >= float(min_rank_q90))].copy()
    if rows.empty:
        return rows
    def _row_numeric(name: str, default: float) -> pd.Series:
        raw = rows[name] if name in rows.columns else pd.Series(default, index=rows.index)
        return pd.to_numeric(raw, errors="coerce").fillna(default)

    rows["best_multiplier"] = _row_numeric("best_multiplier", 1.0)
    rows["best_gain"] = _row_numeric("best_gain", 0.0)
    rows["best_margin"] = _row_numeric("best_margin", 0.0)
    rows["best_gain_per_notional"] = _row_numeric("best_gain_per_notional", 0.0)
    rows["best_margin_per_notional"] = _row_numeric("best_margin_per_notional", 0.0)
    rows["best_nonbaseline_gain"] = _row_numeric("best_nonbaseline_gain", 0.0)
    rows["worst_nonbaseline_gain"] = _row_numeric("worst_nonbaseline_gain", 0.0)
    rows["y_intervene"] = _row_numeric("y_intervene", 0.0)
    rows["group_opportunity_target"] = (
        (rows["y_intervene"] > 0.0)
        & (rows["best_multiplier"] < 1.0)
        & (rows["best_gain"] >= float(material_gain))
        & (rows["best_margin"] >= float(material_margin))
        & (rows["best_gain_per_notional"] >= float(min_gain_per_notional))
        & (rows["best_margin_per_notional"] >= float(min_margin_per_notional))
    )
    hard_negative = (
        ~rows["group_opportunity_target"]
        & (
            (rows["best_multiplier"] >= 1.0)
            | (rows["best_nonbaseline_gain"] <= 0.0)
            | (rows["worst_nonbaseline_gain"] <= -float(material_gain))
        )
        & (rows["worst_nonbaseline_gain"] <= -0.25 * float(material_gain))
    )
    rows["group_opportunity_trainable"] = rows["group_opportunity_target"] | hard_negative
    return rows.sort_values(["timestamp", "strategy_id"])


def _high_rank_group_opportunity_classifier_schedule(
    train_panel: pd.DataFrame,
    eval_panel: pd.DataFrame,
    *,
    material_gain: float = 50.0,
    min_rank_q90: float = 0.70,
    min_precision: float = 0.85,
    max_intervention_rate: float = 0.15,
    top_fractions: tuple[float, ...] = (0.005, 0.01, 0.02, 0.035, 0.05, 0.075, 0.10, 0.15),
    seed: int = 1831,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    train_rows = _group_rows_for_opportunity_classifier(
        train_panel,
        material_gain=float(material_gain),
        min_rank_q90=float(min_rank_q90),
    )
    eval_rows = _group_rows_for_opportunity_classifier(
        eval_panel,
        material_gain=float(material_gain),
        min_rank_q90=float(min_rank_q90),
    )
    diag: dict[str, Any] = {
        "enabled": False,
        "train_rows": int(len(train_rows)),
        "eval_rows": int(len(eval_rows)),
        "train_positive_rows": int(train_rows.get("group_opportunity_target", pd.Series(dtype=bool)).sum()) if not train_rows.empty else 0,
        "material_gain": float(material_gain),
        "min_rank_q90": float(min_rank_q90),
        "min_precision": float(min_precision),
        "max_intervention_rate": float(max_intervention_rate),
        "selected_eval_rows": 0,
        "threshold_source": "no_op_insufficient_group_opportunity_classifier_data",
        "feature_columns_json": "[]",
    }
    empty = pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action"])
    if train_rows.empty or eval_rows.empty:
        return empty, diag
    strategy_categories = sorted(set(train_rows["strategy_id"].astype(str)).union(set(eval_rows["strategy_id"].astype(str))))
    strategy_map = {strategy: idx for idx, strategy in enumerate(strategy_categories)}
    train_rows["strategy_code"] = train_rows["strategy_id"].astype(str).map(strategy_map).fillna(-1).astype(float)
    eval_rows["strategy_code"] = eval_rows["strategy_id"].astype(str).map(strategy_map).fillna(-1).astype(float)
    fit_all = train_rows.loc[train_rows["group_opportunity_trainable"].eq(True)].copy()
    if len(fit_all) < 40 or fit_all["group_opportunity_target"].nunique() < 2:
        return empty, diag
    ts = pd.to_datetime(fit_all["timestamp"], utc=True, errors="coerce")
    cutoff = ts.quantile(0.70) if len(ts.dropna().unique()) >= 8 else ts.max()
    fit_rows = fit_all.loc[ts <= cutoff].copy()
    holdout_rows = fit_all.loc[ts > cutoff].copy()
    if len(fit_rows) < 30 or fit_rows["group_opportunity_target"].nunique() < 2 or len(holdout_rows) < 10:
        fit_rows = fit_all.copy()
        holdout_rows = fit_all.copy()
    initial_feature_cols = _group_opportunity_classifier_feature_cols(fit_rows, max_features=96)
    if len(initial_feature_cols) < 5:
        return empty, diag
    y = fit_rows["group_opportunity_target"].astype(int).to_numpy()
    gain = pd.to_numeric(fit_rows["best_gain"], errors="coerce").fillna(0.0).to_numpy(dtype=float)
    worst = pd.to_numeric(fit_rows["worst_nonbaseline_gain"], errors="coerce").fillna(0.0).to_numpy(dtype=float)
    pos = y.astype(bool)
    pos_rate = max(float(np.mean(pos)), EPSILON)
    neg_rate = max(1.0 - pos_rate, EPSILON)
    weights = np.where(pos, 0.5 / pos_rate, 0.5 / neg_rate)
    pos_scale = max(float(np.nanmedian(np.abs(gain[pos]))) if np.any(pos) else 1.0, 1.0)
    neg_scale = max(float(np.nanmedian(np.abs(worst[~pos]))) if np.any(~pos) else 1.0, 1.0)
    weights[pos] *= 1.0 + 0.25 * np.clip(gain[pos] / pos_scale, 0.0, 10.0)
    weights[~pos] *= 1.0 + 0.75 * np.clip(np.abs(np.minimum(worst[~pos], 0.0)) / neg_scale, 0.0, 20.0)
    weights = np.clip(weights, 0.05, 30.0)
    try:
        from lightgbm import LGBMClassifier

        selector: Any = LGBMClassifier(
            objective="binary",
            n_estimators=140,
            learning_rate=0.035,
            num_leaves=15,
            max_depth=3,
            min_child_samples=max(10, int(0.03 * len(fit_rows))),
            subsample=0.85,
            colsample_bytree=0.85,
            reg_alpha=0.1,
            reg_lambda=3.0,
            scale_pos_weight=float(max((len(y) - y.sum()) / max(y.sum(), 1), 1.0)),
            **_lgbm_deterministic_kwargs(seed),
            verbose=-1,
        )
        x_select, _select_medians = _group_opportunity_classifier_matrix(fit_rows, initial_feature_cols)
        selector.fit(x_select, y, sample_weight=weights)
        importances = np.asarray(getattr(selector, "feature_importances_", np.zeros(len(initial_feature_cols))), dtype=float)
        order = np.argsort(-importances)
        feature_cols = [initial_feature_cols[i] for i in order[:64] if importances[i] > 0.0]
        if len(feature_cols) < min(10, len(initial_feature_cols)):
            feature_cols = [initial_feature_cols[i] for i in order[:64]]
        clf: Any = LGBMClassifier(
            objective="binary",
            n_estimators=180,
            learning_rate=0.035,
            num_leaves=15,
            max_depth=3,
            min_child_samples=max(10, int(0.03 * len(fit_rows))),
            subsample=0.85,
            colsample_bytree=0.85,
            reg_alpha=0.1,
            reg_lambda=3.0,
            scale_pos_weight=float(max((len(y) - y.sum()) / max(y.sum(), 1), 1.0)),
            **_lgbm_deterministic_kwargs(seed + 101),
            verbose=-1,
        )
        x_train, medians = _group_opportunity_classifier_matrix(fit_rows, feature_cols)
        clf.fit(x_train, y, sample_weight=weights)
        x_holdout, _ = _group_opportunity_classifier_matrix(holdout_rows, feature_cols, medians)
        holdout_score = clf.predict_proba(x_holdout)[:, 1]
        x_eval, _ = _group_opportunity_classifier_matrix(eval_rows, feature_cols, medians)
        eval_score = clf.predict_proba(x_eval)[:, 1]
    except Exception:
        return empty, {**diag, "threshold_source": "no_op_group_opportunity_classifier_fit_failed"}
    holdout_scored = holdout_rows.copy()
    holdout_scored["selection_score"] = holdout_score.astype(float)
    holdout_scored["target_int"] = holdout_scored["group_opportunity_target"].astype(int)
    best: dict[str, Any] | None = None
    max_rate = max(min(float(max_intervention_rate), 1.0), 0.0)
    for frac in top_fractions:
        frac_f = max(min(float(frac), max_rate if max_rate > 0.0 else float(frac)), 0.0)
        if frac_f <= 0.0:
            continue
        n_top = max(1, int(np.ceil(len(holdout_scored) * frac_f)))
        selected_holdout = holdout_scored.nlargest(min(n_top, len(holdout_scored)), "selection_score")
        precision = float(selected_holdout["target_int"].mean()) if len(selected_holdout) else 0.0
        gain_sum = float(pd.to_numeric(selected_holdout.get("best_gain"), errors="coerce").fillna(0.0).sum())
        objective = gain_sum if precision >= float(min_precision) else -1e9 + gain_sum
        candidate = {
            "top_fraction": float(frac_f),
            "holdout_precision": precision,
            "holdout_selected": int(len(selected_holdout)),
            "holdout_positive": int(selected_holdout["target_int"].sum()) if len(selected_holdout) else 0,
            "holdout_gain_sum": gain_sum,
            "objective": objective,
        }
        if best is None or float(candidate["objective"]) > float(best["objective"]):
            best = candidate
    if best is None or float(best.get("holdout_precision", 0.0)) < float(min_precision):
        return empty, {
            **diag,
            "enabled": True,
            "initial_feature_count": int(len(initial_feature_cols)),
            "feature_count": int(len(feature_cols)),
            "feature_columns_json": json.dumps([str(c) for c in feature_cols], sort_keys=True),
            "threshold_source": "no_op_no_holdout_threshold_met_precision",
            **({f"holdout_{k}": _json_safe(v) for k, v in (best or {}).items()}),
        }
    scored = eval_rows[["timestamp", "strategy_id"]].copy()
    scored["multiplier"] = 0.0
    scored["selection_score"] = eval_score.astype(float)
    scored["eligible_action"] = True
    n_eval = max(1, int(np.ceil(len(scored) * float(best["top_fraction"]))))
    selected = scored.nlargest(min(n_eval, len(scored)), "selection_score").copy()
    selected["group_opportunity_classifier_score"] = selected["selection_score"].astype(float)
    diag.update(
        {
            "enabled": True,
            "train_fit_rows": int(len(fit_rows)),
            "holdout_rows": int(len(holdout_rows)),
            "train_positive_rows": int(y.sum()),
            "initial_feature_count": int(len(initial_feature_cols)),
            "feature_count": int(len(feature_cols)),
            "feature_columns_json": json.dumps([str(c) for c in feature_cols], sort_keys=True),
            "selected_eval_rows": int(len(selected)),
            "threshold_source": "fold_local_high_rank_group_opportunity_classifier_holdout",
            **{f"holdout_{k}": _json_safe(v) for k, v in best.items()},
        }
    )
    return selected.sort_values(["timestamp", "strategy_id"]), diag


def _low_stage1_missed_oracle_classifier_schedule(
    train_panel: pd.DataFrame,
    eval_panel: pd.DataFrame,
    *,
    eval_action_scores: pd.DataFrame | None = None,
    material_gain: float = 50.0,
    min_rank_q90: float = 0.70,
    max_stage1_p: float = 0.40,
    min_precision: float = 0.85,
    max_intervention_rate: float = 0.05,
    action_tail_rank_weight: float = 0.0,
    top_fractions: tuple[float, ...] = (0.005, 0.01, 0.02, 0.035, 0.05),
    seed: int = 2039,
) -> tuple[pd.DataFrame, dict[str, Any]]:
    train_rows = _group_rows_for_opportunity_classifier(
        train_panel,
        material_gain=float(material_gain),
        min_rank_q90=float(min_rank_q90),
    )
    eval_rows = _group_rows_for_opportunity_classifier(
        eval_panel,
        material_gain=float(material_gain),
        min_rank_q90=float(min_rank_q90),
    )
    diag: dict[str, Any] = {
        "enabled": False,
        "train_rows": int(len(train_rows)),
        "eval_rows": int(len(eval_rows)),
        "train_positive_rows": 0,
        "material_gain": float(material_gain),
        "min_rank_q90": float(min_rank_q90),
        "max_stage1_p": float(max_stage1_p),
        "min_precision": float(min_precision),
        "max_intervention_rate": float(max_intervention_rate),
        "action_tail_rank_weight": float(action_tail_rank_weight),
        "action_tail_rank_feature_count": 0,
        "selected_eval_rows": 0,
        "threshold_source": "no_op_insufficient_low_stage1_missed_oracle_data",
        "feature_columns_json": "[]",
    }
    empty = pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action"])
    if train_rows.empty or eval_rows.empty:
        return empty, diag
    for frame in (train_rows, eval_rows):
        raw_p = frame["p_intervene"] if "p_intervene" in frame.columns else pd.Series(0.0, index=frame.index)
        frame["p_intervene"] = pd.to_numeric(raw_p, errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
    train_rows["missed_oracle_target"] = train_rows["group_opportunity_target"].astype(bool) & (
        train_rows["p_intervene"] <= float(max_stage1_p)
    )
    hard_negative = (
        ~train_rows["missed_oracle_target"].astype(bool)
        & (
            (pd.to_numeric(train_rows.get("best_multiplier"), errors="coerce").fillna(1.0) >= 1.0)
            | (pd.to_numeric(train_rows.get("best_nonbaseline_gain"), errors="coerce").fillna(0.0) <= 0.0)
            | (pd.to_numeric(train_rows.get("worst_nonbaseline_gain"), errors="coerce").fillna(0.0) <= -float(material_gain))
        )
        & (pd.to_numeric(train_rows.get("worst_nonbaseline_gain"), errors="coerce").fillna(0.0) <= -0.25 * float(material_gain))
    )
    train_rows["missed_oracle_trainable"] = train_rows["missed_oracle_target"].astype(bool) | hard_negative.astype(bool)
    eval_rows = eval_rows.loc[pd.to_numeric(eval_rows["p_intervene"], errors="coerce").fillna(0.0) <= float(max_stage1_p)].copy()
    diag.update(
        {
            "eval_rows": int(len(eval_rows)),
            "train_positive_rows": int(train_rows["missed_oracle_target"].sum()),
        }
    )
    if eval_rows.empty:
        return empty, diag
    strategy_categories = sorted(set(train_rows["strategy_id"].astype(str)).union(set(eval_rows["strategy_id"].astype(str))))
    strategy_map = {strategy: idx for idx, strategy in enumerate(strategy_categories)}
    train_rows["strategy_code"] = train_rows["strategy_id"].astype(str).map(strategy_map).fillna(-1).astype(float)
    eval_rows["strategy_code"] = eval_rows["strategy_id"].astype(str).map(strategy_map).fillna(-1).astype(float)
    fit_all = train_rows.loc[train_rows["missed_oracle_trainable"].eq(True)].copy()
    if len(fit_all) < 40 or fit_all["missed_oracle_target"].nunique() < 2:
        return empty, diag
    ts = pd.to_datetime(fit_all["timestamp"], utc=True, errors="coerce")
    cutoff = ts.quantile(0.70) if len(ts.dropna().unique()) >= 8 else ts.max()
    fit_rows = fit_all.loc[ts <= cutoff].copy()
    holdout_rows = fit_all.loc[ts > cutoff].copy()
    if len(fit_rows) < 30 or fit_rows["missed_oracle_target"].nunique() < 2 or len(holdout_rows) < 10:
        fit_rows = fit_all.copy()
        holdout_rows = fit_all.copy()
    initial_feature_cols = _group_opportunity_classifier_feature_cols(fit_rows, max_features=96)
    if len(initial_feature_cols) < 5:
        return empty, diag
    y = fit_rows["missed_oracle_target"].astype(int).to_numpy()
    gain = pd.to_numeric(fit_rows["best_gain"], errors="coerce").fillna(0.0).to_numpy(dtype=float)
    worst = pd.to_numeric(fit_rows["worst_nonbaseline_gain"], errors="coerce").fillna(0.0).to_numpy(dtype=float)
    pos = y.astype(bool)
    pos_rate = max(float(np.mean(pos)), EPSILON)
    neg_rate = max(1.0 - pos_rate, EPSILON)
    weights = np.where(pos, 0.5 / pos_rate, 0.5 / neg_rate)
    pos_scale = max(float(np.nanmedian(np.abs(gain[pos]))) if np.any(pos) else 1.0, 1.0)
    neg_scale = max(float(np.nanmedian(np.abs(worst[~pos]))) if np.any(~pos) else 1.0, 1.0)
    weights[pos] *= 1.0 + 0.35 * np.clip(gain[pos] / pos_scale, 0.0, 10.0)
    weights[~pos] *= 1.0 + 1.00 * np.clip(np.abs(np.minimum(worst[~pos], 0.0)) / neg_scale, 0.0, 20.0)
    weights = np.clip(weights, 0.05, 40.0)
    try:
        from lightgbm import LGBMClassifier

        selector: Any = LGBMClassifier(
            objective="binary",
            n_estimators=160,
            learning_rate=0.03,
            num_leaves=15,
            max_depth=3,
            min_child_samples=max(10, int(0.03 * len(fit_rows))),
            subsample=0.85,
            colsample_bytree=0.85,
            reg_alpha=0.2,
            reg_lambda=4.0,
            scale_pos_weight=float(max((len(y) - y.sum()) / max(y.sum(), 1), 1.0)),
            **_lgbm_deterministic_kwargs(seed),
            verbose=-1,
        )
        x_select, _select_medians = _group_opportunity_classifier_matrix(fit_rows, initial_feature_cols)
        selector.fit(x_select, y, sample_weight=weights)
        importances = np.asarray(getattr(selector, "feature_importances_", np.zeros(len(initial_feature_cols))), dtype=float)
        order = np.argsort(-importances)
        feature_cols = [initial_feature_cols[i] for i in order[:64] if importances[i] > 0.0]
        if len(feature_cols) < min(10, len(initial_feature_cols)):
            feature_cols = [initial_feature_cols[i] for i in order[:64]]
        clf: Any = LGBMClassifier(
            objective="binary",
            n_estimators=220,
            learning_rate=0.03,
            num_leaves=15,
            max_depth=3,
            min_child_samples=max(10, int(0.03 * len(fit_rows))),
            subsample=0.85,
            colsample_bytree=0.85,
            reg_alpha=0.2,
            reg_lambda=4.0,
            scale_pos_weight=float(max((len(y) - y.sum()) / max(y.sum(), 1), 1.0)),
            **_lgbm_deterministic_kwargs(seed + 101),
            verbose=-1,
        )
        x_train, medians = _group_opportunity_classifier_matrix(fit_rows, feature_cols)
        clf.fit(x_train, y, sample_weight=weights)
        x_holdout, _ = _group_opportunity_classifier_matrix(holdout_rows, feature_cols, medians)
        holdout_score = clf.predict_proba(x_holdout)[:, 1]
        x_eval, _ = _group_opportunity_classifier_matrix(eval_rows, feature_cols, medians)
        eval_score = clf.predict_proba(x_eval)[:, 1]
    except Exception:
        return empty, {**diag, "threshold_source": "no_op_low_stage1_missed_oracle_classifier_fit_failed"}
    holdout_scored = holdout_rows.copy()
    holdout_scored["selection_score"] = holdout_score.astype(float)
    holdout_scored["target_int"] = holdout_scored["missed_oracle_target"].astype(int)
    best: dict[str, Any] | None = None
    max_rate = max(min(float(max_intervention_rate), 1.0), 0.0)
    for frac in top_fractions:
        frac_f = max(min(float(frac), max_rate if max_rate > 0.0 else float(frac)), 0.0)
        if frac_f <= 0.0:
            continue
        n_top = max(1, int(np.ceil(len(holdout_scored) * frac_f)))
        selected_holdout = holdout_scored.nlargest(min(n_top, len(holdout_scored)), "selection_score")
        precision = float(selected_holdout["target_int"].mean()) if len(selected_holdout) else 0.0
        gain_sum = float(pd.to_numeric(selected_holdout.get("best_gain"), errors="coerce").fillna(0.0).sum())
        false_harm = float(pd.to_numeric(selected_holdout.get("worst_nonbaseline_gain"), errors="coerce").fillna(0.0).clip(upper=0.0).abs().sum())
        objective = gain_sum - false_harm if precision >= float(min_precision) else -1e9 + gain_sum - false_harm
        candidate = {
            "top_fraction": float(frac_f),
            "holdout_precision": precision,
            "holdout_selected": int(len(selected_holdout)),
            "holdout_positive": int(selected_holdout["target_int"].sum()) if len(selected_holdout) else 0,
            "holdout_gain_sum": gain_sum,
            "holdout_false_harm": false_harm,
            "objective": objective,
        }
        if best is None or float(candidate["objective"]) > float(best["objective"]):
            best = candidate
    if best is None or float(best.get("holdout_precision", 0.0)) < float(min_precision):
        return empty, {
            **diag,
            "enabled": True,
            "initial_feature_count": int(len(initial_feature_cols)),
            "feature_count": int(len(feature_cols)),
            "feature_columns_json": json.dumps([str(c) for c in feature_cols], sort_keys=True),
            "threshold_source": "no_op_no_holdout_threshold_met_low_stage1_missed_oracle_precision",
            **({(str(k) if str(k).startswith("holdout_") else f"holdout_{k}"): _json_safe(v) for k, v in (best or {}).items()}),
        }
    scored = eval_rows[["timestamp", "strategy_id"]].copy()
    scored["multiplier"] = 0.0
    scored["low_stage1_missed_oracle_classifier_score"] = eval_score.astype(float)
    scored["selection_score"] = eval_score.astype(float)
    scored["eligible_action"] = True
    action_tail_cols = [
        "p_action_value_positive",
        "p_action_economic_positive",
        "p_action_positive",
        "cal_positive_rate",
        "cal_mean_delta_J",
        "cal_lcb_mean_delta_J",
        "cal_q10_delta_J",
        "pred_delta_J",
        "ranker_score",
    ]
    action_tail_feature_count = 0
    if eval_action_scores is not None and not eval_action_scores.empty and float(action_tail_rank_weight) > 0.0:
        action_scores = eval_action_scores.copy()
        action_scores["timestamp"] = pd.to_datetime(action_scores["timestamp"], utc=True, errors="coerce")
        action_scores["strategy_id"] = action_scores["strategy_id"].astype(str)
        action_scores["multiplier"] = pd.to_numeric(action_scores.get("multiplier"), errors="coerce").fillna(np.nan)
        action_scores = action_scores.loc[np.isclose(action_scores["multiplier"], 0.0)].copy()
        keep_cols = ["timestamp", "strategy_id"] + [c for c in action_tail_cols if c in action_scores.columns]
        if len(keep_cols) > 2:
            scored = scored.merge(action_scores[keep_cols].drop_duplicates(["timestamp", "strategy_id"]), on=["timestamp", "strategy_id"], how="left")
            rank_parts: list[pd.Series] = []
            for col in action_tail_cols:
                if col not in scored.columns:
                    continue
                vals = pd.to_numeric(scored[col], errors="coerce").replace([np.inf, -np.inf], np.nan)
                if vals.notna().sum() <= 0 or vals.nunique(dropna=True) <= 1:
                    continue
                scored[f"{col}_tail_rank"] = vals.fillna(vals.median()).rank(pct=True, method="average")
                rank_parts.append(scored[f"{col}_tail_rank"])
            action_tail_feature_count = int(len(rank_parts))
            if rank_parts:
                scored["low_stage1_action_tail_rank_score"] = pd.concat(rank_parts, axis=1).mean(axis=1).astype(float)
                scored["low_stage1_classifier_rank_score"] = scored["low_stage1_missed_oracle_classifier_score"].rank(
                    pct=True,
                    method="average",
                )
                weight = float(np.clip(float(action_tail_rank_weight), 0.0, 1.0))
                scored["selection_score"] = (
                    (1.0 - weight) * scored["low_stage1_classifier_rank_score"].astype(float)
                    + weight * scored["low_stage1_action_tail_rank_score"].astype(float)
                )
    n_eval = max(1, int(np.ceil(len(scored) * float(best["top_fraction"]))))
    selected = scored.nlargest(min(n_eval, len(scored)), "selection_score").copy()
    diag.update(
        {
            "enabled": True,
            "train_fit_rows": int(len(fit_rows)),
            "holdout_rows": int(len(holdout_rows)),
            "train_positive_rows": int(y.sum()),
            "initial_feature_count": int(len(initial_feature_cols)),
            "feature_count": int(len(feature_cols)),
            "feature_columns_json": json.dumps([str(c) for c in feature_cols], sort_keys=True),
            "action_tail_rank_feature_count": int(action_tail_feature_count),
            "selected_eval_rows": int(len(selected)),
            "threshold_source": "fold_local_low_stage1_missed_oracle_classifier_holdout",
            **{(str(k) if str(k).startswith("holdout_") else f"holdout_{k}"): _json_safe(v) for k, v in best.items()},
        }
    )
    return selected.sort_values(["timestamp", "strategy_id"]), diag


def _apply_bagged_stage1_safety_gate(scored_groups: pd.DataFrame, thresholds: dict[str, Any]) -> pd.DataFrame:
    work = _apply_stage1_top_fraction_gate(
        scored_groups,
        p_min=float(thresholds.get("p_min", 1.01)),
        stage1_top_fraction=float(thresholds.get("top_fraction", 0.0)),
    )
    if work.empty:
        return work
    safety_mask = _stage1_safety_mask(work, thresholds)
    work["stage1_safety_pass"] = safety_mask.astype(bool)
    work["stage1_group_pass"] = work["stage1_group_pass"].astype(bool) & work["stage1_safety_pass"].astype(bool)
    return work


def _apply_strategy_stage1_gates(scored_groups: pd.DataFrame, strategy_thresholds: pd.DataFrame) -> pd.DataFrame:
    if scored_groups.empty:
        return scored_groups.copy()
    work = scored_groups.copy()
    work["timestamp"] = pd.to_datetime(work["timestamp"], utc=True, errors="coerce")
    work["strategy_id"] = work["strategy_id"].astype(str)
    work["p_intervene"] = pd.to_numeric(work.get("p_intervene"), errors="coerce").fillna(0.0)
    work["group_can_bind"] = pd.to_numeric(work.get("group_can_bind"), errors="coerce").fillna(0.0)
    work["stage1_group_pass"] = False
    if strategy_thresholds.empty:
        return work
    thresholds = strategy_thresholds.copy()
    thresholds["strategy_id"] = thresholds["strategy_id"].astype(str)
    thresholds["p_min"] = pd.to_numeric(thresholds.get("p_min"), errors="coerce").fillna(1.01)
    thresholds["top_fraction"] = pd.to_numeric(thresholds.get("top_fraction"), errors="coerce").fillna(0.0)
    for row in thresholds.itertuples(index=False):
        strategy_id = str(row.strategy_id)
        p_min = float(row.p_min)
        top_fraction = float(row.top_fraction)
        idx = work.index[
            work["strategy_id"].eq(strategy_id)
            & (pd.to_numeric(work["group_can_bind"], errors="coerce").fillna(0.0) > 0.0)
            & (pd.to_numeric(work["p_intervene"], errors="coerce").fillna(0.0) >= p_min)
            & (pd.to_numeric(work["p_intervene"], errors="coerce").fillna(0.0) > 0.0)
        ]
        if len(idx) <= 0:
            continue
        if top_fraction > 0.0:
            n_top = max(1, int(np.ceil(len(idx) * min(max(top_fraction, 0.0), 1.0))))
            idx = work.loc[idx].nlargest(n_top, "p_intervene").index
        work.loc[idx, "stage1_group_pass"] = True
    return work


def _strategy_stage1_oracle_multiplier_schedule(
    scored_groups: pd.DataFrame,
    strategy_thresholds: pd.DataFrame,
) -> pd.DataFrame:
    work = _apply_strategy_stage1_gates(scored_groups, strategy_thresholds)
    if work.empty:
        return pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier"])
    work["best_multiplier"] = pd.to_numeric(work.get("best_multiplier"), errors="coerce").fillna(1.0)
    work["best_gain"] = pd.to_numeric(work.get("best_gain"), errors="coerce").fillna(0.0)
    work["multiplier"] = np.where(
        work["stage1_group_pass"] & (work["best_multiplier"] < 1.0) & (work["best_gain"] > 0.0),
        work["best_multiplier"],
        1.0,
    )
    work["selection_score"] = np.where(work["multiplier"] < 1.0, work["p_intervene"], 0.0)
    return work[["timestamp", "strategy_id", "multiplier", "selection_score", "p_intervene", "stage1_group_pass"]].sort_values(
        ["timestamp", "strategy_id"]
    )


def _apply_size_schedule(candidates: pd.DataFrame, schedule: pd.DataFrame) -> pd.DataFrame:
    if schedule.empty:
        return candidates.copy()
    work = candidates.copy()
    work["timestamp"] = pd.to_datetime(work["timestamp"], utc=True, errors="coerce")
    work["strategy_id"] = work["strategy_id"].astype(str)
    sched = schedule.copy()
    sched["timestamp"] = pd.to_datetime(sched["timestamp"], utc=True, errors="coerce")
    sched["strategy_id"] = sched["strategy_id"].astype(str)
    work = work.merge(sched[["timestamp", "strategy_id", "multiplier"]], on=["timestamp", "strategy_id"], how="left")
    multiplier = pd.to_numeric(work.pop("multiplier"), errors="coerce").fillna(1.0).clip(lower=0.0, upper=1.0)
    base = (
        pd.to_numeric(work.get("portfolio_size_multiplier"), errors="coerce").fillna(1.0)
        if "portfolio_size_multiplier" in work.columns
        else pd.Series(1.0, index=work.index)
    )
    work["portfolio_size_multiplier"] = (base * multiplier).clip(lower=0.0, upper=1.0)
    work.attrs.pop("portfolio_policy_candidates_normalised", None)
    return work


def _replay_arm(arm: str, candidates: pd.DataFrame, params: Any, ev_curve: dict[str, Any], schedule: pd.DataFrame, market_mode: str) -> tuple[dict[str, Any], pd.DataFrame]:
    arm_candidates = _apply_size_schedule(candidates, schedule)
    decisions, _equity, metrics = replay_candidates(arm_candidates, params, mode="global_auction", ev_curve=ev_curve, market_mode=market_mode)
    accepted = _accepted_trades(arm_candidates, decisions)
    row = _global_metrics_row(arm, metrics, schedule if not schedule.empty else pd.DataFrame({"multiplier": [1.0]}), accepted)
    return row, accepted


def _schedule_action_quality(arm: str, fold_id: int, schedule: pd.DataFrame, eval_panel: pd.DataFrame) -> tuple[dict[str, Any], pd.DataFrame]:
    """Compare scheduled actions to exact-state counterfactual labels.

    This is a diagnostic only. It does not feed the policy. A useful sparse
    intervention learner should place its highest predicted-benefit rows in
    buckets with positive realized delta_J and should avoid selecting many
    negative-value non-noop actions.
    """
    base = {
        "arm": arm,
        "fold_id": int(fold_id),
        "scheduled_groups": 0,
        "intervention_count": 0,
        "intervention_rate": 0.0,
        "bind_count": 0,
        "positive_action_count": 0,
        "positive_action_rate": 0.0,
        "realized_delta_full_J_sum": 0.0,
        "realized_delta_full_J_mean": 0.0,
        "realized_delta_full_J_median": 0.0,
        "realized_delta_immediate_J_sum": 0.0,
        "realized_delta_full_net_pnl_sum": 0.0,
        "realized_delta_full_cost_pnl_sum": 0.0,
        "realized_delta_full_turnover_sum": 0.0,
        "selected_group_best_delta_full_J_sum": 0.0,
        "selected_group_best_delta_full_J_mean": 0.0,
        "selected_group_best_multiplier_match_count": 0,
        "selected_group_best_multiplier_match_rate": 0.0,
        "selector_regret_full_J_sum": 0.0,
        "selector_regret_full_J_mean": 0.0,
        "oracle_positive_group_count": 0,
        "oracle_positive_group_capture_rate": 0.0,
        "oracle_gain_capture_ratio": 0.0,
    }
    if schedule.empty or eval_panel.empty:
        return base, pd.DataFrame()
    sched = schedule.copy()
    panel = eval_panel.copy()
    sched["timestamp"] = pd.to_datetime(sched["timestamp"], utc=True, errors="coerce")
    panel["timestamp"] = pd.to_datetime(panel["timestamp"], utc=True, errors="coerce")
    sched["strategy_id"] = sched["strategy_id"].astype(str)
    panel["strategy_id"] = panel["strategy_id"].astype(str)
    sched["multiplier"] = pd.to_numeric(sched["multiplier"], errors="coerce").fillna(1.0).astype(float)
    panel["multiplier"] = pd.to_numeric(panel["multiplier"], errors="coerce").astype(float)
    label_cols = [
        "timestamp",
        "strategy_id",
        "multiplier",
        "delta_full_J",
        "delta_immediate_J",
        "delta_full_net_pnl",
        "delta_full_cost_pnl",
        "delta_full_turnover",
        "action_binds",
        "best_multiplier",
        "best_gain",
        "y_intervene",
    ]
    labels = panel[[c for c in label_cols if c in panel.columns]].copy()
    merged = sched.merge(labels, on=["timestamp", "strategy_id", "multiplier"], how="left")
    merged["delta_full_J"] = pd.to_numeric(merged.get("delta_full_J"), errors="coerce").fillna(0.0)
    merged["delta_immediate_J"] = pd.to_numeric(merged.get("delta_immediate_J"), errors="coerce").fillna(0.0)
    merged["delta_full_net_pnl"] = pd.to_numeric(merged.get("delta_full_net_pnl"), errors="coerce").fillna(0.0)
    merged["delta_full_cost_pnl"] = pd.to_numeric(merged.get("delta_full_cost_pnl"), errors="coerce").fillna(0.0)
    merged["delta_full_turnover"] = pd.to_numeric(merged.get("delta_full_turnover"), errors="coerce").fillna(0.0)
    merged["action_binds"] = pd.to_numeric(merged.get("action_binds"), errors="coerce").fillna(0.0)
    merged["best_gain"] = pd.to_numeric(merged.get("best_gain"), errors="coerce").fillna(0.0)
    merged["y_intervene"] = pd.to_numeric(merged.get("y_intervene"), errors="coerce").fillna(0.0)
    intervention = pd.to_numeric(merged["multiplier"], errors="coerce").fillna(1.0) < 1.0
    selected = merged.loc[intervention].copy()
    alternatives = panel.copy()
    alternatives["delta_full_J"] = pd.to_numeric(alternatives.get("delta_full_J"), errors="coerce").fillna(0.0)
    alternatives["delta_immediate_J"] = pd.to_numeric(alternatives.get("delta_immediate_J"), errors="coerce").fillna(0.0)
    alternatives["multiplier"] = pd.to_numeric(alternatives["multiplier"], errors="coerce").astype(float)
    best_alternatives = (
        alternatives.sort_values(
            ["timestamp", "strategy_id", "delta_full_J", "delta_immediate_J", "multiplier"],
            ascending=[True, True, False, False, False],
        )
        .drop_duplicates(["timestamp", "strategy_id"])
        [["timestamp", "strategy_id", "multiplier", "delta_full_J"]]
        .rename(columns={"multiplier": "group_best_multiplier", "delta_full_J": "group_best_delta_full_J"})
    )
    if len(selected):
        selected = selected.merge(best_alternatives, on=["timestamp", "strategy_id"], how="left")
        selected["group_best_delta_full_J"] = pd.to_numeric(selected.get("group_best_delta_full_J"), errors="coerce").fillna(0.0)
        selected["group_best_multiplier"] = pd.to_numeric(selected.get("group_best_multiplier"), errors="coerce").fillna(1.0)
        selected["selector_regret_full_J"] = selected["group_best_delta_full_J"] - selected["delta_full_J"]
        selected["selected_group_best_multiplier_match"] = np.isclose(
            pd.to_numeric(selected["multiplier"], errors="coerce").fillna(1.0),
            selected["group_best_multiplier"],
        )
    oracle_positive = merged.drop_duplicates(["timestamp", "strategy_id"]).loc[lambda x: x["y_intervene"] > 0.0].copy()
    captured = selected.merge(
        oracle_positive[["timestamp", "strategy_id", "best_gain"]],
        on=["timestamp", "strategy_id"],
        how="inner",
        suffixes=("", "_oracle"),
    )
    material_positive = selected["delta_full_J"] > MATERIAL_DELTA_EPS if len(selected) else pd.Series(dtype=bool)
    base.update(
        {
            "scheduled_groups": int(len(merged)),
            "intervention_count": int(intervention.sum()),
            "intervention_rate": float(intervention.mean()) if len(merged) else 0.0,
            "bind_count": int((selected["action_binds"] > 0.0).sum()) if len(selected) else 0,
            "positive_action_count": int(material_positive.sum()) if len(selected) else 0,
            "positive_action_rate": float(material_positive.mean()) if len(selected) else 0.0,
            "realized_delta_full_J_sum": float(selected["delta_full_J"].sum()) if len(selected) else 0.0,
            "realized_delta_full_J_mean": float(selected["delta_full_J"].mean()) if len(selected) else 0.0,
            "realized_delta_full_J_median": float(selected["delta_full_J"].median()) if len(selected) else 0.0,
            "realized_delta_immediate_J_sum": float(selected["delta_immediate_J"].sum()) if len(selected) else 0.0,
            "realized_delta_full_net_pnl_sum": float(selected["delta_full_net_pnl"].sum()) if len(selected) else 0.0,
            "realized_delta_full_cost_pnl_sum": float(selected["delta_full_cost_pnl"].sum()) if len(selected) else 0.0,
            "realized_delta_full_turnover_sum": float(selected["delta_full_turnover"].sum()) if len(selected) else 0.0,
            "selected_group_best_delta_full_J_sum": float(selected["group_best_delta_full_J"].sum()) if len(selected) else 0.0,
            "selected_group_best_delta_full_J_mean": float(selected["group_best_delta_full_J"].mean()) if len(selected) else 0.0,
            "selected_group_best_multiplier_match_count": int(selected["selected_group_best_multiplier_match"].sum()) if len(selected) else 0,
            "selected_group_best_multiplier_match_rate": float(selected["selected_group_best_multiplier_match"].mean()) if len(selected) else 0.0,
            "selector_regret_full_J_sum": float(selected["selector_regret_full_J"].sum()) if len(selected) else 0.0,
            "selector_regret_full_J_mean": float(selected["selector_regret_full_J"].mean()) if len(selected) else 0.0,
            "oracle_positive_group_count": int(len(oracle_positive)),
            "oracle_positive_group_capture_rate": float(len(captured) / len(oracle_positive)) if len(oracle_positive) else 0.0,
            "oracle_gain_capture_ratio": float(captured["delta_full_J"].sum() / max(oracle_positive["best_gain"].sum(), EPSILON)) if len(oracle_positive) else 0.0,
        }
    )

    score_cols = [
        c
        for c in ("selection_score", "p_benefit", "p_intervene", "vote_share", "positive_value_share", "median_pred_delta_J", "pred_delta_J", "q10_delta_J")
        if c in merged.columns
    ]
    decile_frames: list[pd.DataFrame] = []
    for score_col in score_cols:
        scored = merged.copy()
        scored[score_col] = pd.to_numeric(scored[score_col], errors="coerce")
        scored = scored.loc[scored[score_col].notna()].copy()
        if scored.empty:
            continue
        unique_scores = scored[score_col].nunique(dropna=True)
        if unique_scores <= 1:
            scored["score_bucket"] = 0
        else:
            scored["score_bucket"] = pd.qcut(scored[score_col].rank(method="first"), q=min(10, len(scored), unique_scores), labels=False, duplicates="drop")
        dec = scored.groupby("score_bucket", as_index=False).agg(
            rows=("delta_full_J", "size"),
            score_min=(score_col, "min"),
            score_max=(score_col, "max"),
            intervention_rate=("multiplier", lambda s: float((pd.to_numeric(s, errors="coerce").fillna(1.0) < 1.0).mean())),
            mean_delta_full_J=("delta_full_J", "mean"),
            median_delta_full_J=("delta_full_J", "median"),
            positive_delta_share=("delta_full_J", lambda s: float((s > MATERIAL_DELTA_EPS).mean())),
        )
        dec["arm"] = arm
        dec["fold_id"] = int(fold_id)
        dec["score_column"] = score_col
        decile_frames.append(dec)
    deciles = pd.concat(decile_frames, ignore_index=True) if decile_frames else pd.DataFrame()
    return base, deciles


def _selector_transfer_diagnostics(arm: str, fold_id: int, schedule: pd.DataFrame, eval_panel: pd.DataFrame) -> pd.DataFrame:
    """Persist eval-fold selected/missed oracle groups for transfer debugging."""
    if schedule.empty or eval_panel.empty:
        return pd.DataFrame()
    sched = schedule.copy()
    panel = eval_panel.copy()
    sched["timestamp"] = pd.to_datetime(sched["timestamp"], utc=True, errors="coerce")
    panel["timestamp"] = pd.to_datetime(panel["timestamp"], utc=True, errors="coerce")
    sched["strategy_id"] = sched["strategy_id"].astype(str)
    panel["strategy_id"] = panel["strategy_id"].astype(str)
    sched["multiplier"] = pd.to_numeric(sched["multiplier"], errors="coerce").fillna(1.0).astype(float)
    panel["multiplier"] = pd.to_numeric(panel["multiplier"], errors="coerce").fillna(1.0).astype(float)

    group_cols = ["timestamp", "strategy_id"]
    label_cols = [
        "best_multiplier",
        "best_gain",
        "best_margin",
        "best_nonbaseline_gain",
        "best_nonbaseline_multiplier",
        "y_intervene",
        "affected_notional",
        "group_can_bind",
    ]
    groups = panel[group_cols + [c for c in label_cols if c in panel.columns]].drop_duplicates(group_cols).copy()
    alternatives = panel.copy()
    alternatives["delta_full_J"] = pd.to_numeric(alternatives.get("delta_full_J"), errors="coerce").fillna(0.0)
    alternatives["delta_immediate_J"] = pd.to_numeric(alternatives.get("delta_immediate_J"), errors="coerce").fillna(0.0)
    best_alternatives = (
        alternatives.sort_values(
            ["timestamp", "strategy_id", "delta_full_J", "delta_immediate_J", "multiplier"],
            ascending=[True, True, False, False, False],
        )
        .drop_duplicates(group_cols)
        [["timestamp", "strategy_id", "multiplier", "delta_full_J", "delta_immediate_J"]]
        .rename(
            columns={
                "multiplier": "oracle_best_multiplier",
                "delta_full_J": "oracle_best_delta_full_J",
                "delta_immediate_J": "oracle_best_delta_immediate_J",
            }
        )
    )
    selected_value_cols = [
        "delta_full_J",
        "delta_immediate_J",
        "delta_full_net_pnl",
        "delta_full_cost_pnl",
        "action_binds",
    ]
    selected_exact = sched.merge(
        panel[group_cols + ["multiplier"] + [c for c in selected_value_cols if c in panel.columns]],
        on=group_cols + ["multiplier"],
        how="left",
    )
    selected_exact = selected_exact.rename(
        columns={
            "multiplier": "selected_multiplier",
            "delta_full_J": "selected_delta_full_J",
            "delta_immediate_J": "selected_delta_immediate_J",
            "delta_full_net_pnl": "selected_delta_full_net_pnl",
            "delta_full_cost_pnl": "selected_delta_full_cost_pnl",
            "action_binds": "selected_action_binds",
        }
    )
    out = groups.merge(best_alternatives, on=group_cols, how="left").merge(selected_exact, on=group_cols, how="left")
    out["selected_multiplier"] = pd.to_numeric(out.get("selected_multiplier"), errors="coerce").fillna(1.0)
    out["selected"] = out["selected_multiplier"] < 1.0
    out["selected_delta_full_J"] = pd.to_numeric(out.get("selected_delta_full_J"), errors="coerce").fillna(0.0)
    out["oracle_best_delta_full_J"] = pd.to_numeric(out.get("oracle_best_delta_full_J"), errors="coerce").fillna(0.0)
    out["selector_regret_full_J"] = out["oracle_best_delta_full_J"] - out["selected_delta_full_J"]
    out["selected_is_oracle_best_multiplier"] = np.isclose(
        out["selected_multiplier"],
        pd.to_numeric(out.get("oracle_best_multiplier"), errors="coerce").fillna(1.0),
    )
    out["missed_positive_oracle"] = (out["oracle_best_delta_full_J"] > 0.0) & ~out["selected"]
    secondary_candidate_cols = [
        c
        for c in [
            "union_secondary_available",
            "calibrated_group_hurdle_opportunity_secondary",
            "calibrated_group_hurdle_no_action_tail_secondary",
            "calibrated_group_hurdle_foldfit_action_acceptance_secondary",
            "calibrated_group_hurdle_positive_value_acceptance_secondary",
            "rank_calibrated_value_secondary",
            "low_stage1_missed_oracle_classifier_precondition_secondary_rows",
            "low_stage1_missed_oracle_classifier_accepted_secondary_rows",
        ]
        if c in out.columns
    ]
    if secondary_candidate_cols:
        secondary_available = pd.Series(False, index=out.index)
        for col in secondary_candidate_cols:
            secondary_available = secondary_available | (pd.to_numeric(out[col], errors="coerce").fillna(0.0) > 0.0)
    else:
        secondary_available = pd.Series(False, index=out.index)
    out["selector_secondary_candidate_available"] = secondary_available
    out["selector_transfer_reason"] = "not_oracle_candidate"
    oracle_miss = pd.to_numeric(out.get("y_intervene"), errors="coerce").fillna(0.0).gt(0.0) & ~out["selected"]
    out.loc[out["selected"] & (out["selected_delta_full_J"] > MATERIAL_DELTA_EPS), "selector_transfer_reason"] = "selected_positive"
    out.loc[out["selected"] & (out["selected_delta_full_J"] <= MATERIAL_DELTA_EPS), "selector_transfer_reason"] = "selected_nonpositive"
    out.loc[oracle_miss & ~secondary_available, "selector_transfer_reason"] = "missed_no_secondary_candidate"
    if "nonoverlap_suppressed" in out.columns:
        out.loc[
            oracle_miss & secondary_available & pd.to_numeric(out["nonoverlap_suppressed"], errors="coerce").fillna(0.0).gt(0.0),
            "selector_transfer_reason",
        ] = "blocked_nonoverlap_suppression"
    if "secondary_acceptance_pass" in out.columns:
        out.loc[
            oracle_miss
            & secondary_available
            & pd.to_numeric(out["secondary_acceptance_pass"], errors="coerce").fillna(0.0).le(0.0),
            "selector_transfer_reason",
        ] = "blocked_secondary_acceptance"
    if "action_secondary_acceptance_pass" in out.columns:
        out.loc[
            oracle_miss
            & secondary_available
            & pd.to_numeric(out["action_secondary_acceptance_pass"], errors="coerce").fillna(0.0).le(0.0),
            "selector_transfer_reason",
        ] = "blocked_action_acceptance"
    if {
        "calibrated_group_hurdle_no_action_tail_secondary",
        "calibrated_group_hurdle_positive_value_acceptance_secondary",
    }.issubset(out.columns):
        out.loc[
            oracle_miss
            & pd.to_numeric(out["calibrated_group_hurdle_no_action_tail_secondary"], errors="coerce").fillna(0.0).gt(0.0)
            & pd.to_numeric(out["calibrated_group_hurdle_positive_value_acceptance_secondary"], errors="coerce").fillna(0.0).le(0.0),
            "selector_transfer_reason",
        ] = "blocked_positive_value_floor"
    out.loc[
        oracle_miss & secondary_available & out["selector_transfer_reason"].eq("not_oracle_candidate"),
        "selector_transfer_reason",
    ] = "secondary_candidate_not_selected"
    out["fold_id"] = int(fold_id)
    out["arm"] = arm
    out["oracle_gain_rank_in_fold"] = (
        out["oracle_best_delta_full_J"].rank(method="first", ascending=False).astype(int) if len(out) else pd.Series(dtype=int)
    )
    keep = [
        "arm",
        "fold_id",
        "timestamp",
        "strategy_id",
        "selected",
        "selected_multiplier",
        "selected_delta_full_J",
        "selected_delta_immediate_J",
        "selected_delta_full_net_pnl",
        "selected_delta_full_cost_pnl",
        "selected_action_binds",
        "oracle_best_multiplier",
        "oracle_best_delta_full_J",
        "oracle_best_delta_immediate_J",
        "selector_regret_full_J",
        "selected_is_oracle_best_multiplier",
        "missed_positive_oracle",
        "oracle_gain_rank_in_fold",
        "best_multiplier",
        "best_gain",
        "best_margin",
        "best_nonbaseline_gain",
        "best_nonbaseline_multiplier",
        "y_intervene",
        "affected_notional",
        "group_can_bind",
        "selection_score",
        "p_intervene",
        "stage1_group_pass",
        "pred_delta_J",
        "cal_mean_delta_J",
        "cal_lcb_mean_delta_J",
        "cal_q25_delta_J",
        "cal_q10_delta_J",
        "cal_positive_rate",
        "calibration_bin_n",
        "p_action_positive",
        "p_action_value_positive",
        "p_action_economic_positive",
        "ranker_score",
        "ranker_score_margin",
        "pred_delta_margin",
        "eligible_action",
        "union_primary_active",
        "union_secondary_available",
        "union_preferred_source",
        "nonoverlap_suppressed",
        "secondary_acceptance_pass",
        "opportunity_recall_score",
        "action_secondary_acceptance_pass",
        "stage1_cal_positive_rate",
        "stage1_cal_mean_gain",
        "stage1_cal_lcb_mean_gain",
        "calibrated_group_hurdle_score",
        "calibrated_group_hurdle_opportunity_secondary",
        "calibrated_group_hurdle_no_action_tail_secondary",
        "calibrated_group_hurdle_foldfit_action_acceptance_secondary",
        "calibrated_group_hurdle_positive_value_acceptance_secondary",
        "rank_calibrated_value_secondary",
        "rank_calibrated_value_score",
        "low_stage1_missed_oracle_classifier_score",
        "low_stage1_missed_oracle_classifier_selected_eval_rows",
        "low_stage1_missed_oracle_classifier_raw_secondary_rows",
        "low_stage1_missed_oracle_classifier_precondition_secondary_rows",
        "low_stage1_missed_oracle_classifier_accepted_secondary_rows",
        "low_stage1_missed_oracle_classifier_stage1_lcb_guard_pass",
        "selector_secondary_candidate_available",
        "selector_transfer_reason",
    ]
    return out[[c for c in keep if c in out.columns]].sort_values(["fold_id", "arm", "oracle_gain_rank_in_fold"])


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--broad-candidates", type=Path, default=DEFAULT_TRAIN_BROAD)
    parser.add_argument("--deployable-candidates", type=Path, default=DEFAULT_TRAIN_DEPLOYABLE)
    parser.add_argument("--policy-manifest", type=Path, default=DEFAULT_POLICY_MANIFEST)
    parser.add_argument("--policy-variant", default="refit_bar4_strategy_bar2")
    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUTPUT_DIR)
    parser.add_argument("--horizon-hours", type=int, default=72)
    parser.add_argument("--embargo-hours", type=int, default=96)
    parser.add_argument("--min-train-hours", type=int, default=336)
    parser.add_argument("--fold-hours", type=int, default=168)
    parser.add_argument("--max-folds", type=int, default=3)
    parser.add_argument("--max-train-timestamps", type=int, default=96)
    parser.add_argument("--max-eval-timestamps", type=int, default=48)
    parser.add_argument("--panel-cache", type=Path, default=None)
    parser.add_argument("--reuse-panel-cache", action="store_true")
    parser.add_argument("--lambda-dd", type=float, default=0.25)
    parser.add_argument("--lambda-turnover", type=float, default=0.0)
    parser.add_argument("--epsilon", type=float, default=0.0)
    parser.add_argument("--epsilon-gain", type=float, default=10.0)
    parser.add_argument("--epsilon-margin", type=float, default=5.0)
    parser.add_argument("--epsilon-gain-per-notional", type=float, default=0.001)
    parser.add_argument("--epsilon-margin-per-notional", type=float, default=0.0005)
    parser.add_argument("--uniqueness-horizon-hours", type=float, default=72.0)
    parser.add_argument("--event-thin-hours", type=float, default=0.0)
    parser.add_argument("--recency-half-life-hours", type=float, default=0.0)
    parser.add_argument("--hurdle-train-max-timestamps", type=int, default=0)
    parser.add_argument("--sparse-threshold-holdout-frac", type=float, default=0.0)
    parser.add_argument("--compact-stage1-features", action="store_true")
    parser.add_argument(
        "--stage1-context-interactions",
        action="store_true",
        help="Diagnostic: include causal Stage-1 pressure/interaction features before fold-local feature selection.",
    )
    parser.add_argument(
        "--stage1-training-label-mode",
        choices=[
            "strict",
            "relaxed_gain",
            "broad_clean_gain",
            "decomposed_gain",
            "immediate_gain",
            "capacity_gain",
            "moderate_capacity_gain",
            "zero_cut_gain",
        ],
        default="strict",
        help="Stage-1 training target. Evaluation/calibration always keep strict y_intervene.",
    )
    parser.add_argument("--stage1-action-impact-features", action="store_true")
    parser.add_argument("--stage1-action-impact-feature-cap", type=int, default=4)
    parser.add_argument("--stage1-trivial-negative-sample-frac", type=float, default=1.0)
    parser.add_argument("--group-negative-harm-weight", type=float, default=0.05)
    parser.add_argument("--stage1-positive-gain-weight", type=float, default=0.0)
    parser.add_argument(
        "--action-positive-gain-weight",
        type=float,
        default=0.20,
        help="Bounded positive-gain weight for action-value rows. Strict evaluation labels and acceptance gates are unchanged.",
    )
    parser.add_argument("--action-negative-loss-weight", type=float, default=0.03)
    parser.add_argument("--p-min", type=float, default=0.65)
    parser.add_argument("--hurdle-p-min", type=float, default=0.40)
    parser.add_argument("--high-confidence-hurdle-p-min", type=float, default=0.50)
    parser.add_argument("--hurdle-value-min", type=float, default=0.0)
    parser.add_argument("--ranker-margin-min", type=float, default=0.25)
    parser.add_argument("--pred-delta-margin-min", type=float, default=10.0)
    parser.add_argument("--pred-delta-margin-min-per-notional", type=float, default=0.0005)
    parser.add_argument("--calibrated-positive-rate-min", type=float, default=0.55)
    parser.add_argument("--action-positive-min", type=float, default=0.55)
    parser.add_argument("--calibrated-mean-min", type=float, default=0.0)
    parser.add_argument("--calibration-min-bin-n", type=int, default=0)
    parser.add_argument("--learned-min-multiplier", type=float, default=0.0)
    parser.add_argument("--group-action-noop-confidence-max", type=float, default=0.60)
    parser.add_argument("--positive-multiplier-confidence-min", type=float, default=0.95)
    parser.add_argument("--bag-vote-min", type=float, default=0.80)
    parser.add_argument("--bag-choice-min", type=float, default=0.60)
    parser.add_argument("--market-mode", default="perps")
    parser.add_argument(
        "--arms",
        default="all",
        help="Comma-separated arm short codes or full names to evaluate. C0 is always included. Use 'all' for every arm.",
    )
    args = parser.parse_args()
    selected_arms = _parse_selected_arms(args.arms)

    args.output_dir.mkdir(parents=True, exist_ok=True)
    params, policy_payload = _load_policy_params(args.policy_manifest, args.policy_variant)
    broad = normalise_candidate_table(_load_candidates(args.broad_candidates))
    deployable = normalise_candidate_table(_load_candidates(args.deployable_candidates))
    cached_panel = _read_panel_cache(args.panel_cache) if args.reuse_panel_cache else None
    if cached_panel is not None and not cached_panel.empty:
        cached_panel["timestamp"] = pd.to_datetime(cached_panel["timestamp"], utc=True, errors="coerce")
    folds = _build_folds(
        broad["timestamp"],
        min_train_hours=int(args.min_train_hours),
        fold_hours=int(args.fold_hours),
        embargo_hours=int(args.embargo_hours),
        max_folds=args.max_folds,
    )
    summary_rows: list[dict[str, Any]] = []
    panel_frames: list[pd.DataFrame] = []
    schedule_frames: list[pd.DataFrame] = []
    parity_frames: list[pd.DataFrame] = []
    action_quality_rows: list[dict[str, Any]] = []
    decile_frames: list[pd.DataFrame] = []
    selector_transfer_frames: list[pd.DataFrame] = []
    eval_action_score_frames: list[pd.DataFrame] = []
    stage1_diagnostic_frames: list[pd.DataFrame] = []
    stage1_group_score_frames: list[pd.DataFrame] = []
    selected_feature_rows: list[dict[str, Any]] = []
    action_calibration_frames: list[pd.DataFrame] = []
    gate_threshold_rows: list[dict[str, Any]] = []
    for fold in folds:
        fold_id = int(fold["fold_id"])
        train_end = pd.Timestamp(fold["train_end"])
        eval_start = pd.Timestamp(fold["eval_start"])
        eval_end = pd.Timestamp(fold["eval_end"]) + pd.Timedelta(nanoseconds=1)
        train_candidates = broad.loc[_timestamp_mask(broad, end=train_end + pd.Timedelta(nanoseconds=1))].copy()
        eval_candidates = broad.loc[_timestamp_mask(broad, start=eval_start, end=eval_end)].copy()
        if len(train_candidates) < 100 or len(eval_candidates) < 20:
            continue
        ev_curve = fit_hierarchical_ev_curves(deployable.loc[_timestamp_mask(deployable, end=train_end + pd.Timedelta(nanoseconds=1))].copy())
        train_ts = _timestamp_sample(train_candidates["timestamp"], int(args.max_train_timestamps))
        eval_ts = _timestamp_sample(eval_candidates["timestamp"], int(args.max_eval_timestamps))
        train_parity = pd.DataFrame()
        eval_parity = pd.DataFrame()
        train_panel = pd.DataFrame()
        eval_panel = pd.DataFrame()
        built_panel_this_fold = False
        if cached_panel is not None and {"fold_id", "split"}.issubset(cached_panel.columns):
            train_panel = cached_panel.loc[
                (pd.to_numeric(cached_panel["fold_id"], errors="coerce").eq(fold_id))
                & cached_panel["split"].astype(str).eq("train")
            ].copy()
            eval_panel = cached_panel.loc[
                (pd.to_numeric(cached_panel["fold_id"], errors="coerce").eq(fold_id))
                & cached_panel["split"].astype(str).eq("eval")
            ].copy()
        if train_panel.empty or eval_panel.empty:
            train_panel, train_parity = _build_exact_size_panel(
                train_candidates,
                params,
                ev_curve,
                timestamps=train_ts,
                horizon_hours=int(args.horizon_hours),
                lambda_dd=float(args.lambda_dd),
                lambda_turnover=float(args.lambda_turnover),
                market_mode=args.market_mode,
            )
            eval_panel, eval_parity = _build_exact_size_panel(
                eval_candidates,
                params,
                ev_curve,
                timestamps=eval_ts,
                horizon_hours=int(args.horizon_hours),
                lambda_dd=float(args.lambda_dd),
                lambda_turnover=float(args.lambda_turnover),
                market_mode=args.market_mode,
            )
            built_panel_this_fold = True
        if train_panel.empty or eval_panel.empty:
            continue
        train_panel = _annotate_group_labels(
            train_panel,
            epsilon_gain=float(args.epsilon_gain),
            epsilon_margin=float(args.epsilon_margin),
            epsilon_gain_per_notional=float(args.epsilon_gain_per_notional),
            epsilon_margin_per_notional=float(args.epsilon_margin_per_notional),
        )
        eval_panel = _annotate_group_labels(
            eval_panel,
            epsilon_gain=float(args.epsilon_gain),
            epsilon_margin=float(args.epsilon_margin),
            epsilon_gain_per_notional=float(args.epsilon_gain_per_notional),
            epsilon_margin_per_notional=float(args.epsilon_margin_per_notional),
        )
