        def c0_schedule_factory() -> pd.DataFrame:
            schedule = pd.MultiIndex.from_product(
                [
                    pd.to_datetime(eval_candidates["timestamp"], utc=True).drop_duplicates().sort_values(),
                    sorted(eval_candidates["strategy_id"].astype(str).unique()),
                ],
                names=["timestamp", "strategy_id"],
            ).to_frame(index=False)
            schedule["multiplier"] = 1.0
            return schedule

        def c3da_union_schedule_factory() -> pd.DataFrame:
            primary = _apply_multiplier_consensus_group_action_schedule_acceptance(
                _predict_hurdle_schedule(
                    eval_candidates,
                    params,
                    ev_curve,
                    hurdle,
                    timestamps=eval_ts,
                    mode="group_action_family_only",
                    p_min=0.0,
                    value_min=float(args.hurdle_value_min),
                    min_multiplier=float(args.learned_min_multiplier),
                    allowed_multipliers={0.0, 0.5},
                    horizon_hours=int(args.horizon_hours),
                    market_mode=args.market_mode,
                    stage1_top_fraction=0.0,
                    precomputed_groups=_apply_bagged_stage1_safety_gate(bagged_stage1_scores, bagged_safety_stage1_thresholds),
                ),
                bagged_safety_direct_group_action_family_acceptance_thresholds,
                allowed_multipliers={0.0, 0.5},
                multiplier_confidence_min=0.50,
                pred_delta_max=0.0,
            )
            secondary = _apply_high_conf_multiplier_value_schedule_gate(
                _predict_hurdle_schedule(
                    eval_candidates,
                    params,
                    ev_curve,
                    hurdle,
                    timestamps=eval_ts,
                    mode="group_multiplier_only",
                    p_min=0.0,
                    value_min=float(args.hurdle_value_min),
                    min_multiplier=float(args.learned_min_multiplier),
                    allowed_multipliers={0.0, 0.5},
                    horizon_hours=int(args.horizon_hours),
                    market_mode=args.market_mode,
                    stage1_top_fraction=0.0,
                    precomputed_groups=_apply_bagged_stage1_safety_gate(bagged_stage1_scores, bagged_safety_stage1_thresholds),
                ),
                allowed_multipliers={0.0, 0.5},
                p_intervene_min=0.40,
                multiplier_confidence_min=0.90,
                pred_delta_max=0.0,
                require_family_support=True,
                family_noop_confidence_min=0.70,
                family_agreement_confidence_min=0.60,
                low_conf_family_agreement_pred_delta_min=-50.0,
            )
            return _combine_preferred_action_schedules(primary, secondary)

        def c3db_nonoverlap_schedule_factory() -> pd.DataFrame:
            return _suppress_nearby_union_actions(
                c3da_union_schedule_factory(),
                min_gap_hours=48.0,
                prefer_source="secondary",
            )

        def c3do_union_schedule_factory() -> pd.DataFrame:
            primary = c3db_nonoverlap_schedule_factory().copy()
            primary["union_preferred_source"] = "primary"
            secondary = _strategy_stage1_calibrated_fixed_schedule(
                _score_hurdle_panel_groups(eval_panel, hurdle),
                strategy_stage1_calibrated_fixed_zero_thresholds,
            ).copy()
            secondary["union_preferred_source"] = "secondary"
            return _suppress_nearby_union_actions(
                pd.concat([primary, secondary], ignore_index=False),
                min_gap_hours=72.0,
                prefer_source="primary",
            )

