        def c3fj_c3ed_stage1_lcb_guard_schedule_factory() -> pd.DataFrame:
            schedule = c3ed_pressure_opportunity_action_tail_veto_union_schedule_factory().copy()
            lcb = pd.to_numeric(schedule.get("stage1_cal_lcb_mean_gain"), errors="coerce")
            finite_lcb = lcb.notna()
            guard_pass = (~finite_lcb) | lcb.ge(20.0)
            schedule["stage1_lcb_guard_enabled"] = True
            schedule["stage1_lcb_guard_min"] = 20.0
            schedule["stage1_lcb_guard_pass"] = guard_pass.astype(bool)
            return schedule.loc[guard_pass].copy()

