        def _low_stage1_missed_oracle_union_schedule_factory(
            *,
            min_precision: float,
            max_intervention_rate: float,
            label: str,
            apply_action_tail_gate: bool = True,
            action_tail_rank_weight: float = 0.0,
            secondary_stage1_lcb_mean_gain_min: float = -np.inf,
            prefer_source: str = "primary",
        ) -> pd.DataFrame:
            primary = c3ed_pressure_opportunity_action_tail_veto_union_schedule_factory().copy()
            primary["union_preferred_source"] = "primary"
            secondary, classifier_diag = _low_stage1_missed_oracle_classifier_schedule(
                train_panel,
                eval_panel,
                eval_action_scores=_score_hurdle_panel_actions(eval_panel, hurdle) if float(action_tail_rank_weight) > 0.0 else None,
                material_gain=float(args.epsilon_gain),
                min_rank_q90=0.70,
                max_stage1_p=0.40,
                min_precision=float(min_precision),
                max_intervention_rate=float(max_intervention_rate),
                action_tail_rank_weight=float(action_tail_rank_weight),
                seed=2039 + int(fold_id),
            )
            classifier_diag_json = json.dumps(_json_safe(classifier_diag), sort_keys=True)
            raw_secondary_count = int(len(secondary))
            primary["low_stage1_missed_oracle_classifier_enabled"] = bool(classifier_diag.get("enabled", False))
            primary["low_stage1_missed_oracle_classifier_label"] = str(label)
            primary["low_stage1_missed_oracle_classifier_diag"] = classifier_diag_json
            primary["low_stage1_missed_oracle_classifier_selected_eval_rows"] = int(
                classifier_diag.get("selected_eval_rows", raw_secondary_count) or 0
            )
            primary["low_stage1_missed_oracle_classifier_raw_secondary_rows"] = raw_secondary_count
            primary["low_stage1_missed_oracle_classifier_precondition_secondary_rows"] = 0
            secondary = secondary.copy()
            secondary["union_preferred_source"] = "secondary"
            secondary["low_stage1_missed_oracle_classifier_enabled"] = bool(classifier_diag.get("enabled", False))
            secondary["low_stage1_missed_oracle_classifier_label"] = str(label)
            secondary["low_stage1_missed_oracle_classifier_selected_eval_rows"] = int(
                classifier_diag.get("selected_eval_rows", raw_secondary_count) or 0
            )
            secondary["low_stage1_missed_oracle_classifier_raw_secondary_rows"] = raw_secondary_count
            secondary = _apply_secondary_schedule_acceptance(
                secondary,
                eval_panel,
                {
                    "enabled": True,
                    "min_thresholds": {"strategy_rank_q90": 0.70},
                    "max_thresholds": {"strategy_open_count": 2.0},
                },
            )
            precondition_secondary_count = int(
                (
                    pd.to_numeric(secondary.get("multiplier"), errors="coerce").fillna(1.0).lt(1.0)
                    & secondary.get("eligible_action", pd.Series(False, index=secondary.index)).fillna(False).astype(bool)
                ).sum()
            ) if not secondary.empty else 0
            primary["low_stage1_missed_oracle_classifier_precondition_secondary_rows"] = precondition_secondary_count
            secondary["low_stage1_missed_oracle_classifier_precondition_secondary_rows"] = precondition_secondary_count
            primary["low_stage1_missed_oracle_classifier_action_tail_gate_enabled"] = bool(apply_action_tail_gate)
            secondary["low_stage1_missed_oracle_classifier_action_tail_gate_enabled"] = bool(apply_action_tail_gate)
            primary["low_stage1_missed_oracle_classifier_action_tail_rank_weight"] = float(action_tail_rank_weight)
            secondary["low_stage1_missed_oracle_classifier_action_tail_rank_weight"] = float(action_tail_rank_weight)
            primary["low_stage1_missed_oracle_classifier_stage1_lcb_mean_gain_min"] = float(secondary_stage1_lcb_mean_gain_min)
            secondary["low_stage1_missed_oracle_classifier_stage1_lcb_mean_gain_min"] = float(secondary_stage1_lcb_mean_gain_min)
            primary["low_stage1_missed_oracle_classifier_union_prefer_source"] = str(prefer_source)
            secondary["low_stage1_missed_oracle_classifier_union_prefer_source"] = str(prefer_source)
            if apply_action_tail_gate:
                secondary = _apply_action_secondary_schedule_acceptance(
                    secondary,
                    _score_hurdle_panel_actions(eval_panel, hurdle),
                    {
                        "enabled": True,
                        "p_action_economic_positive_min": -np.inf,
                        "p_action_positive_min": -np.inf,
                        "cal_positive_rate_min": -np.inf,
                        "cal_mean_delta_J_min": -np.inf,
                        "cal_lcb_mean_delta_J_min": -np.inf,
                        "cal_q10_delta_J_min": -90.0,
                        "pred_delta_J_min": -np.inf,
                        "ranker_score_min": -np.inf,
                        "top_fraction": 0.0,
                    },
                    default_pass=False,
                )
            else:
                secondary["action_secondary_acceptance_pass"] = (
                    pd.to_numeric(secondary.get("multiplier"), errors="coerce").fillna(1.0).lt(1.0)
                    & secondary.get("eligible_action", pd.Series(False, index=secondary.index)).fillna(False).astype(bool)
                )
            if np.isfinite(float(secondary_stage1_lcb_mean_gain_min)):
                stage1_lcb = pd.to_numeric(secondary.get("stage1_cal_lcb_mean_gain"), errors="coerce")
                lcb_pass = stage1_lcb.ge(float(secondary_stage1_lcb_mean_gain_min))
                secondary["low_stage1_missed_oracle_classifier_stage1_lcb_guard_pass"] = lcb_pass.fillna(False).astype(bool)
                secondary["eligible_action"] = (
                    secondary.get("eligible_action", pd.Series(False, index=secondary.index)).fillna(False).astype(bool)
                    & secondary["low_stage1_missed_oracle_classifier_stage1_lcb_guard_pass"]
                )
            else:
                secondary["low_stage1_missed_oracle_classifier_stage1_lcb_guard_pass"] = (
                    pd.to_numeric(secondary.get("multiplier"), errors="coerce").fillna(1.0).lt(1.0)
                    & secondary.get("eligible_action", pd.Series(False, index=secondary.index)).fillna(False).astype(bool)
                )
            accepted_secondary_count = int(
                (
                    pd.to_numeric(secondary.get("multiplier"), errors="coerce").fillna(1.0).lt(1.0)
                    & secondary.get("eligible_action", pd.Series(False, index=secondary.index)).fillna(False).astype(bool)
                ).sum()
            ) if not secondary.empty else 0
            primary["low_stage1_missed_oracle_classifier_accepted_secondary_rows"] = accepted_secondary_count
            secondary["low_stage1_missed_oracle_classifier_accepted_secondary_rows"] = accepted_secondary_count
            stage1_lcb_guard_pass_rows = int(
                secondary.get("low_stage1_missed_oracle_classifier_stage1_lcb_guard_pass", pd.Series(False, index=secondary.index))
                .fillna(False)
                .astype(bool)
                .sum()
            ) if not secondary.empty else 0
            primary["low_stage1_missed_oracle_classifier_stage1_lcb_guard_pass_rows"] = stage1_lcb_guard_pass_rows
            secondary["low_stage1_missed_oracle_classifier_stage1_lcb_guard_pass_rows"] = stage1_lcb_guard_pass_rows
            secondary["low_stage1_missed_oracle_classifier_diag"] = json.dumps(_json_safe(classifier_diag), sort_keys=True)
            return _suppress_nearby_union_actions(
                pd.concat([primary, secondary], ignore_index=False),
                min_gap_hours=72.0,
                prefer_source=str(prefer_source),
            )

