            calibrated_secondary = _calibrated_group_hurdle_schedule(
                scored_eval_group_hurdle_actions,
                calibrated_group_hurdle_recall_thresholds,
                scored_eval_group_hurdle_groups,
            ).copy()
            if not calibrated_secondary.empty:
                calibrated_secondary = _apply_secondary_schedule_acceptance(
                    calibrated_secondary,
                    eval_panel,
                    {
                        "enabled": True,
                        "min_thresholds": {"strategy_rank_q90": 0.70},
                        "max_thresholds": {"strategy_open_count": 2.0},
                    },
                )
                calibrated_secondary = _apply_action_secondary_schedule_acceptance(
                    calibrated_secondary,
                    scored_eval_group_hurdle_actions,
                    {
                        "enabled": True,
                        "p_action_economic_positive_min": -np.inf,
                        "p_action_positive_min": -np.inf,
                        "cal_positive_rate_min": -np.inf,
                        "cal_mean_delta_J_min": -np.inf,
                        "cal_lcb_mean_delta_J_min": -np.inf,
                        "cal_q10_delta_J_min": -90.0,
                        "pred_delta_J_min": -np.inf,
                        "ranker_score_min": -np.inf,
                        "top_fraction": 0.0,
                    },
                    default_pass=False,
                )
            key_cols = ["timestamp", "strategy_id"]
            empty_secondary = pd.DataFrame(columns=["timestamp", "strategy_id", "multiplier", "selection_score", "eligible_action"])
            high_rank_selected = high_rank_secondary.loc[
                pd.to_numeric(high_rank_secondary.get("multiplier"), errors="coerce").fillna(1.0) < 1.0
            ].copy() if not high_rank_secondary.empty else empty_secondary.copy()
            calibrated_selected = calibrated_secondary.loc[
                pd.to_numeric(calibrated_secondary.get("multiplier"), errors="coerce").fillna(1.0) < 1.0
            ].copy() if not calibrated_secondary.empty else empty_secondary.copy()
            if high_rank_selected.empty or calibrated_selected.empty:
                consensus_secondary = empty_secondary.copy()
            else:
                high_rank_selected["timestamp"] = pd.to_datetime(high_rank_selected["timestamp"], utc=True, errors="coerce")
                high_rank_selected["strategy_id"] = high_rank_selected["strategy_id"].astype(str)
                high_rank_selected = high_rank_selected.rename(
                    columns={
                        "selection_score": "high_rank_group_classifier_selection_score",
                        "multiplier": "high_rank_group_classifier_multiplier",
                    }
                )
                calibrated_selected["timestamp"] = pd.to_datetime(calibrated_selected["timestamp"], utc=True, errors="coerce")
                calibrated_selected["strategy_id"] = calibrated_selected["strategy_id"].astype(str)
                consensus_secondary = calibrated_selected.merge(
                    high_rank_selected[
                        key_cols
                        + [
                            c
                            for c in [
                                "high_rank_group_classifier_selection_score",
                                "high_rank_group_classifier_multiplier",
                                "group_opportunity_classifier_score",
                            ]
                            if c in high_rank_selected.columns
                        ]
                    ].drop_duplicates(key_cols),
                    on=key_cols,
                    how="inner",
                )
                if not consensus_secondary.empty:
                    cal_multiplier = pd.to_numeric(consensus_secondary.get("multiplier"), errors="coerce").fillna(1.0)
                    high_rank_multiplier = pd.to_numeric(
                        consensus_secondary.get("high_rank_group_classifier_multiplier"),
                        errors="coerce",
                    ).fillna(1.0)
                    consensus_secondary["multiplier"] = np.maximum(cal_multiplier.to_numpy(dtype=float), high_rank_multiplier.to_numpy(dtype=float))
                    cal_score = pd.to_numeric(consensus_secondary.get("selection_score"), errors="coerce").fillna(0.0).clip(lower=0.0)
                    rank_score = pd.to_numeric(
                        consensus_secondary.get("high_rank_group_classifier_selection_score"),
                        errors="coerce",
                    ).fillna(0.0).clip(lower=0.0)
                    consensus_secondary["selection_score"] = np.sqrt((1.0 + cal_score) * (1.0 + rank_score)) - 1.0
                    consensus_secondary = consensus_secondary.loc[
                        pd.to_numeric(consensus_secondary["multiplier"], errors="coerce").fillna(1.0) < 1.0
                    ].copy()
            if not consensus_secondary.empty:
                consensus_secondary["union_preferred_source"] = "secondary"
                consensus_secondary["high_rank_calibrated_group_hurdle_consensus_secondary"] = True
                consensus_secondary["group_opportunity_classifier_enabled"] = bool(classifier_diag.get("enabled", False))
            return _suppress_nearby_union_actions(
                pd.concat([primary, consensus_secondary], ignore_index=False),
                min_gap_hours=72.0,
                prefer_source="primary",
            )

